	/**
	 * Clears all persisted and in-memory loot data (drops, trips, aggregates).
	 */
	public void clearAllData() {
		synchronized (listViewDropArray) {
			listViewDropArray.clear();
		}
		synchronized (npcLootAggregates) {
			npcLootAggregates.clear();
