		synchronized (trips) {
			trips.clear();
		}

		storageService.saveDrops(new ArrayList<>());
		storageService.saveTrips(new ArrayList<>());
		storageService.saveCollapsedNpcs(new HashSet<>());

		SwingUtilities.invokeLater(() -> panel.rebuildAfterClear());
