/**
 * A sub-view panel that shows a comparison table for selected trips.
 * Metrics are column headers, trips are rows.
 */
public class TripComparisonPanel extends JPanel {
    private static final Color FOCUS_COLOR = new Color(0x5E, 0x9E, 0xD6);

    private final List<Trip> allTrips;
    private final Set<Integer> selectedTripIds = new HashSet<>();
    private final JPanel tablePanel;
    private final JPanel checklistPanel;
    private final Runnable onBackAction;
    private final EnhancedLootTrackerPlugin plugin;

    private JTextField filterField;
    private String filterText = "";
    private Timer filterDebounceTimer;
    // Mirrors the 200ms debounce used by the list/grouped/trip view filters in
    // EnhancedLootTrackerPanel; declared locally since that constant is private there.
    private static final int FILTER_DEBOUNCE_MS = 200;

    public TripComparisonPanel(List<Trip> allTrips, int preSelectedTripId, Runnable onBackAction, EnhancedLootTrackerPlugin plugin) {
        this.allTrips = allTrips;
        this.onBackAction = onBackAction;
        this.plugin = plugin;
        this.selectedTripIds.add(preSelectedTripId);

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setAlignmentX(Component.LEFT_ALIGNMENT);

        // Back button
        JPanel backPanel = new JPanel(new FlowLayout(FlowLayout.LEADING, 0, 0));
        backPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        backPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        backPanel.setBorder(new EmptyBorder(0, 0, 8, 0));
        JButton backButton = new JButton("\u2190 Back to trips");
        backButton.setFont(FontManager.getRunescapeSmallFont());
        backButton.setForeground(Color.LIGHT_GRAY);
        backButton.setContentAreaFilled(false);
        backButton.setBorderPainted(false);
        backButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        backButton.getAccessibleContext().setAccessibleName("Back to trips");
        backButton.addActionListener(e -> onBackAction.run());
        addKeyboardFocusIndicator(backButton);
        backPanel.add(backButton);
        add(backPanel);

        // Checklist header + select all / deselect all
        JPanel checklistHeaderPanel = new JPanel(new FlowLayout(FlowLayout.CENTER, 5, 0));
        checklistHeaderPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        checklistHeaderPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        checklistHeaderPanel.setBorder(new EmptyBorder(0, 0, 10, 0));

        JLabel selectLabel = new JLabel("Select trips:");
        selectLabel.setFont(FontManager.getRunescapeSmallFont());
        selectLabel.setForeground(Color.LIGHT_GRAY);
        checklistHeaderPanel.add(selectLabel);

        JButton selectAllButton = new JButton("All");
        selectAllButton.setFont(FontManager.getRunescapeSmallFont());
        selectAllButton.setForeground(Color.LIGHT_GRAY);
        selectAllButton.setContentAreaFilled(false);
        selectAllButton.setBorderPainted(false);
        selectAllButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        selectAllButton.getAccessibleContext().setAccessibleName("Select all trips");
        selectAllButton.addActionListener(e -> {
            // Operate only on trips matching the active filter; filtered-out
            // trips keep their current selection state.
            for (Trip trip : allTrips) {
                if (matchesFilter(trip)) {
                    selectedTripIds.add(trip.getTripId());
                }
            }
            rebuildChecklist();
            rebuildTable();
        });
        addKeyboardFocusIndicator(selectAllButton);
        checklistHeaderPanel.add(selectAllButton);

        JLabel separator = new JLabel("|");
        separator.setForeground(new Color(0xB0, 0xB0, 0xB0));
        checklistHeaderPanel.add(separator);

        JButton deselectAllButton = new JButton("None");
        deselectAllButton.setFont(FontManager.getRunescapeSmallFont());
        deselectAllButton.setForeground(Color.LIGHT_GRAY);
        deselectAllButton.setContentAreaFilled(false);
        deselectAllButton.setBorderPainted(false);
        deselectAllButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        deselectAllButton.getAccessibleContext().setAccessibleName("Deselect all trips");
        deselectAllButton.addActionListener(e -> {
            // Deselect only trips matching the active filter; filtered-out
            // trips keep their current selection state (do NOT clear()).
            for (Trip trip : allTrips) {
                if (matchesFilter(trip)) {
                    selectedTripIds.remove(trip.getTripId());
                }
            }
            rebuildChecklist();
            rebuildTable();
        });
        addKeyboardFocusIndicator(deselectAllButton);
        checklistHeaderPanel.add(deselectAllButton);

        add(checklistHeaderPanel);

        // Filter bar over the checklist (mirrors the list/grouped/trip view filters)
        add(buildChecklistFilterPanel());

        // Trip checkboxes
        checklistPanel = new JPanel();
        checklistPanel.setLayout(new BoxLayout(checklistPanel, BoxLayout.Y_AXIS));
        checklistPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        checklistPanel.setBorder(new EmptyBorder(0, 7, 10, 7));
        checklistPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        rebuildChecklist();
        add(checklistPanel);

        // Export buttons
        JPanel exportPanel = new JPanel(new FlowLayout(FlowLayout.CENTER, 3, 0));
        exportPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        exportPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        exportPanel.setBorder(new EmptyBorder(0, 0, 12, 0));

        JLabel exportLabel = new JLabel("Export:");
        exportLabel.setFont(FontManager.getRunescapeSmallFont());
        exportLabel.setForeground(Color.LIGHT_GRAY);
        exportPanel.add(exportLabel);

        JButton exportCsvButton = new JButton("CSV");
        exportCsvButton.setFont(FontManager.getRunescapeSmallFont());
        exportCsvButton.setForeground(Color.LIGHT_GRAY);
        exportCsvButton.setContentAreaFilled(false);
        exportCsvButton.setBorderPainted(false);
        exportCsvButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        exportCsvButton.getAccessibleContext().setAccessibleName("Export comparison as CSV");
        exportCsvButton.addActionListener(e -> exportCsv());
        addKeyboardFocusIndicator(exportCsvButton);
        exportPanel.add(exportCsvButton);

        JLabel sep1 = new JLabel("|");
        sep1.setForeground(new Color(0xB0, 0xB0, 0xB0));
        exportPanel.add(sep1);

        JButton exportJsonButton = new JButton("JSON");
        exportJsonButton.setFont(FontManager.getRunescapeSmallFont());
        exportJsonButton.setForeground(Color.LIGHT_GRAY);
        exportJsonButton.setContentAreaFilled(false);
        exportJsonButton.setBorderPainted(false);
        exportJsonButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        exportJsonButton.getAccessibleContext().setAccessibleName("Export comparison as JSON");
        exportJsonButton.addActionListener(e -> exportJson());
        addKeyboardFocusIndicator(exportJsonButton);
        exportPanel.add(exportJsonButton);

        JLabel sep2 = new JLabel("|");
        sep2.setForeground(new Color(0xB0, 0xB0, 0xB0));
        exportPanel.add(sep2);

        JButton exportPrettyButton = new JButton("Pretty");
        exportPrettyButton.setFont(FontManager.getRunescapeSmallFont());
        exportPrettyButton.setForeground(Color.LIGHT_GRAY);
        exportPrettyButton.setContentAreaFilled(false);
        exportPrettyButton.setBorderPainted(false);
        exportPrettyButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        exportPrettyButton.getAccessibleContext().setAccessibleName("Export comparison as plain text for Discord");
        exportPrettyButton.addActionListener(e -> exportPretty());
        addKeyboardFocusIndicator(exportPrettyButton);
        exportPanel.add(exportPrettyButton);

        add(exportPanel);

        // Comparison table
        tablePanel = new JPanel();
        tablePanel.setLayout(new BoxLayout(tablePanel, BoxLayout.Y_AXIS));
        tablePanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        tablePanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(tablePanel);

        rebuildTable();
    }

    private JPanel buildChecklistFilterPanel() {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        panel.setBorder(new EmptyBorder(0, 7, 8, 7));

        filterField = new JTextField();
        filterField.setFont(FontManager.getRunescapeSmallFont());
        filterField.setToolTipText("Filter by trip name");
        filterField.putClientProperty("JTextField.placeholderText", "Type to filter...");
        filterField.getAccessibleContext().setAccessibleName("Filter trips by name");
        filterField.getDocument().addDocumentListener(new DocumentListener() {
            @Override
            public void insertUpdate(DocumentEvent e) { onChecklistFilterChanged(); }
            @Override
            public void removeUpdate(DocumentEvent e) { onChecklistFilterChanged(); }
            @Override
            public void changedUpdate(DocumentEvent e) { onChecklistFilterChanged(); }
        });

        JButton clearButton = new JButton("\u2715");
        clearButton.setFont(FontManager.getRunescapeSmallFont());
        clearButton.setPreferredSize(new Dimension(20, 20));
        clearButton.setToolTipText("Clear filter");
        clearButton.setContentAreaFilled(false);
        clearButton.setBorderPainted(false);
        clearButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        clearButton.addActionListener(e -> filterField.setText(""));

        panel.add(filterField, BorderLayout.CENTER);
        panel.add(clearButton, BorderLayout.EAST);

        return panel;
    }

    private void onChecklistFilterChanged() {
        if (filterDebounceTimer == null) {
            filterDebounceTimer = new Timer(FILTER_DEBOUNCE_MS, e -> applyChecklistFilter());
            filterDebounceTimer.setRepeats(false);
        }
        filterDebounceTimer.restart();
    }

    private void applyChecklistFilter() {
        filterText = filterField.getText().trim().toLowerCase();
        rebuildChecklist();
    }

    /**
     * Single source of truth for which trips are currently visible in the
     * checklist. Both {@link #rebuildChecklist()} and the "All"/"None" button
     * handlers use this so "visible" and "affected by All/None" can never diverge.
     */
    private boolean matchesFilter(Trip trip) {
        return filterText.isEmpty() || trip.getTripName().toLowerCase().contains(filterText);
    }

    private void rebuildChecklist() {
        checklistPanel.removeAll();
        int shown = 0;
        for (Trip trip : allTrips) {
            if (!matchesFilter(trip)) {
                continue;
            }
            JCheckBox checkBox = new JCheckBox(trip.getTripName());
            checkBox.setFont(FontManager.getRunescapeSmallFont());
            checkBox.setForeground(Color.LIGHT_GRAY);
            checkBox.setBackground(ColorScheme.DARK_GRAY_COLOR);
            checkBox.setAlignmentX(Component.LEFT_ALIGNMENT);
            checkBox.setMaximumSize(new Dimension(Integer.MAX_VALUE, checkBox.getPreferredSize().height));
            checkBox.setSelected(selectedTripIds.contains(trip.getTripId()));
            checkBox.addActionListener(e -> {
                if (checkBox.isSelected()) {
                    selectedTripIds.add(trip.getTripId());
                } else {
                    selectedTripIds.remove(trip.getTripId());
                }
                rebuildTable();
            });
            addKeyboardFocusIndicator(checkBox);
            checklistPanel.add(checkBox);
            shown++;
        }

        if (shown == 0) {
            JLabel noMatch = new JLabel("No trips match");
            noMatch.setFont(FontManager.getRunescapeSmallFont());
            noMatch.setForeground(new Color(0xB0, 0xB0, 0xB0));
            noMatch.setBorder(new EmptyBorder(10, 7, 10, 7));
            noMatch.setAlignmentX(Component.LEFT_ALIGNMENT);
            checklistPanel.add(noMatch);
        }

        checklistPanel.revalidate();
        checklistPanel.repaint();
    }

    private void rebuildTable() {
        tablePanel.removeAll();

        List<Trip> selected = new ArrayList<>();
        for (Trip trip : allTrips) {
            if (selectedTripIds.contains(trip.getTripId())) {
                selected.add(trip);
            }
        }

        if (selected.size() < 2) {
            JLabel hint = new JLabel("Select at least 2 trips to compare.");
            hint.setFont(FontManager.getRunescapeSmallFont());
            hint.setForeground(new Color(0xB0, 0xB0, 0xB0));
            hint.setBorder(new EmptyBorder(10, 7, 10, 7));
            tablePanel.add(hint);
        } else {
            // Header row
            tablePanel.add(buildHeaderRow());

            // Data rows (one per trip)
            for (Trip trip : selected) {
                tablePanel.add(buildTripRow(trip));
            }
        }

        tablePanel.revalidate();
        tablePanel.repaint();
    }

    private JPanel buildHeaderRow() {
        JPanel row = new JPanel(new GridLayout(1, 5, 4, 0));
        row.setBackground(ColorScheme.SCROLL_TRACK_COLOR);
        row.setBorder(new EmptyBorder(6, 7, 6, 7));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 25));

        String[] headers = {"Kills", "Time", "Value", "GP/hr", "GP/kill"};
        for (String header : headers) {
            JLabel label = new JLabel(header, SwingConstants.CENTER);
            label.setFont(FontManager.getRunescapeSmallFont());
            label.setForeground(Color.ORANGE);
            row.add(label);
        }

        return row;
    }

    private JPanel buildTripRow(Trip trip) {
        JPanel container = new JPanel();
        container.setLayout(new BoxLayout(container, BoxLayout.Y_AXIS));
        container.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
        container.setBorder(new EmptyBorder(5, 7, 5, 7));
        container.setMaximumSize(new Dimension(Integer.MAX_VALUE, 45));

        // Trip name
        JLabel nameLabel = new JLabel(trip.getTripName(), SwingConstants.CENTER);
        nameLabel.setFont(FontManager.getRunescapeSmallFont());
        nameLabel.setForeground(new Color(0xE0, 0x6C, 0x5C));
        nameLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        container.add(nameLabel);

        // Metrics row (respects exclusions)
        AdjustedTripStats stats = getAdjustedStats(trip);
        JPanel metricsRow = new JPanel(new GridLayout(1, 5, 4, 0));
        metricsRow.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
        metricsRow.setBorder(new EmptyBorder(2, 0, 0, 0));

        metricsRow.add(buildMetricLabel(String.valueOf(stats.kills)));
        metricsRow.add(buildMetricLabel(trip.calculateTripDuration()));
        metricsRow.add(buildMetricLabel(FormatUtil.shortenNumber(stats.value)));
        metricsRow.add(buildMetricLabel(FormatUtil.shortenNumber(stats.gpPerHour)));
        metricsRow.add(buildMetricLabel(FormatUtil.shortenNumber(stats.gpPerKill)));

        container.add(metricsRow);
        return container;
    }

    private JLabel buildMetricLabel(String text) {
        JLabel label = new JLabel(text, SwingConstants.CENTER);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(Color.LIGHT_GRAY);
        return label;
    }

    private List<Trip> getSelectedTrips() {
        List<Trip> selected = new ArrayList<>();
        for (Trip trip : allTrips) {
            if (selectedTripIds.contains(trip.getTripId())) {
                selected.add(trip);
            }
        }
        return selected;
    }

    private void exportCsv() {
        List<Trip> selected = getSelectedTrips();
        if (selected.isEmpty()) {
            return;
        }

        StringBuilder sb = new StringBuilder();
        sb.append("Trip Name,Kills,Duration (s),Value,GP/hr,GP/kill,Start,End\n");
        for (Trip trip : selected) {
            AdjustedTripStats stats = getAdjustedStats(trip);
            sb.append(escapeCsv(trip.getTripName())).append(",");
            sb.append(stats.kills).append(",");
            sb.append(trip.getDurationSeconds()).append(",");
            sb.append(stats.value).append(",");
            sb.append(stats.gpPerHour).append(",");
            sb.append(stats.gpPerKill).append(",");
            sb.append(escapeCsv(formatIso(trip.getTripStartTimeEpoch()))).append(",");
            sb.append(escapeCsv(trip.getTripEndTimeEpoch() > 0 ? formatIso(trip.getTripEndTimeEpoch()) : "n/a")).append("\n");
        }

        copyToClipboard(sb.toString());
        JOptionPane.showMessageDialog(this, "CSV copied to clipboard!", "Export", JOptionPane.INFORMATION_MESSAGE);
    }

    private void exportJson() {
        List<Trip> selected = getSelectedTrips();
        if (selected.isEmpty()) {
            return;
        }

        StringBuilder sb = new StringBuilder();
        sb.append("[\n");
        for (int i = 0; i < selected.size(); i++) {
            Trip trip = selected.get(i);
            AdjustedTripStats stats = getAdjustedStats(trip);
            sb.append("  {\n");
            sb.append("    \"name\": \"").append(trip.getTripName().replace("\"", "\\\"")).append("\",\n");
            sb.append("    \"kills\": ").append(stats.kills).append(",\n");
            sb.append("    \"durationSeconds\": ").append(trip.getDurationSeconds()).append(",\n");
            sb.append("    \"value\": ").append(stats.value).append(",\n");
            sb.append("    \"gpPerHour\": ").append(stats.gpPerHour).append(",\n");
            sb.append("    \"gpPerKill\": ").append(stats.gpPerKill).append(",\n");
            sb.append("    \"start\": \"").append(formatIso(trip.getTripStartTimeEpoch())).append("\",\n");
            sb.append("    \"end\": \"").append(trip.getTripEndTimeEpoch() > 0 ? formatIso(trip.getTripEndTimeEpoch()) : "n/a").append("\"\n");
            sb.append("  }");
            if (i < selected.size() - 1) sb.append(",");
            sb.append("\n");
        }
        sb.append("]");

        copyToClipboard(sb.toString());
        JOptionPane.showMessageDialog(this, "JSON copied to clipboard!", "Export", JOptionPane.INFORMATION_MESSAGE);
    }

    private void exportPretty() {
        List<Trip> selected = getSelectedTrips();
        if (selected.isEmpty()) {
            return;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < selected.size(); i++) {
            Trip trip = selected.get(i);
            AdjustedTripStats stats = getAdjustedStats(trip);

            sb.append(trip.getTripName()).append("\n");
            sb.append("  Kills: ").append(stats.kills);
            sb.append(" | Duration: ").append(trip.calculateTripDuration()).append("\n");
            sb.append("  Value: ").append(FormatUtil.shortenNumber(stats.value)).append(" gp");
            sb.append(" | GP/hr: ").append(FormatUtil.shortenNumber(stats.gpPerHour));
            sb.append(" | GP/kill: ").append(FormatUtil.shortenNumber(stats.gpPerKill)).append("\n");

            if (i < selected.size() - 1) {
                sb.append("\n");
            }
        }

        copyToClipboard(sb.toString());
        JOptionPane.showMessageDialog(this, "Pretty text copied to clipboard!", "Export", JOptionPane.INFORMATION_MESSAGE);
    }

    private AdjustedTripStats getAdjustedStats(Trip trip) {
        Set<String> excludedItems = plugin.getExcludedItems();
        Set<String> excludedNpcs = plugin.getExcludedNpcs();

        long adjustedValue = trip.getTripValue();
        int adjustedKills = trip.getTripKills();

        for (NpcLootAggregate agg : trip.getTripAggregates()) {
            if (excludedNpcs.contains(agg.getNpcName().toLowerCase().trim())) {
                adjustedKills -= agg.getNumberOfKills();
                for (TrackableDroppedItem item : agg.getDroppedItems()) {
                    adjustedValue -= item.getTotalGePrice();
                }
            } else {
                for (TrackableDroppedItem item : agg.getDroppedItems()) {
                    if (excludedItems.contains(item.getItemName().toLowerCase().trim())) {
                        adjustedValue -= item.getTotalGePrice();
                    }
                }
            }
        }

        long durationSeconds = trip.getDurationSeconds();
        long gpPerHour = durationSeconds > 0 ? (adjustedValue * 3600L) / durationSeconds : 0;
        long gpPerKill = adjustedKills > 0 ? adjustedValue / adjustedKills : 0;

        return new AdjustedTripStats(adjustedKills, adjustedValue, gpPerHour, gpPerKill);
    }

    private static class AdjustedTripStats {
        final int kills;
        final long value;
        final long gpPerHour;
        final long gpPerKill;

        AdjustedTripStats(int kills, long value, long gpPerHour, long gpPerKill) {
            this.kills = kills;
            this.value = value;
            this.gpPerHour = gpPerHour;
            this.gpPerKill = gpPerKill;
        }
    }

    private void copyToClipboard(String text) {
        java.awt.datatransfer.StringSelection selection = new java.awt.datatransfer.StringSelection(text);
        java.awt.Toolkit.getDefaultToolkit().getSystemClipboard().setContents(selection, null);
    }

    private String escapeCsv(String value) {
        if (value.contains(",") || value.contains("\"") || value.contains("\n")) {
            return "\"" + value.replace("\"", "\"\"") + "\"";
        }
        return value;
    }

    private String formatIso(long epochMillis) {
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss");
        return sdf.format(new java.util.Date(epochMillis));
    }

    private static final javax.swing.border.Border FOCUS_PLACEHOLDER_BORDER = new EmptyBorder(2, 2, 2, 2);
    private static final javax.swing.border.Border FOCUS_VISIBLE_BORDER = new LineBorder(FOCUS_COLOR, 2);

    /**
     * Adds a keyboard-only focus indicator (blue outline) to a component.
     * Only shows when focus is gained via keyboard, not mouse click.
     * Pre-allocates border space so layout doesn't shift.
     */
    private static void addKeyboardFocusIndicator(JComponent component) {
        // Pre-allocate the same insets so the component size stays constant
        if (component instanceof AbstractButton) {
            ((AbstractButton) component).setBorderPainted(true);
        }
        component.setBorder(FOCUS_PLACEHOLDER_BORDER);

        component.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override
            public void mousePressed(java.awt.event.MouseEvent e) {
                component.putClientProperty("focusedByMouse", Boolean.TRUE);
            }
        });
        component.addFocusListener(new FocusAdapter() {
            @Override
            public void focusGained(FocusEvent e) {
                if (Boolean.TRUE.equals(component.getClientProperty("focusedByMouse"))) {
                    component.putClientProperty("focusedByMouse", null);
                    return;
                }
                component.setBorder(FOCUS_VISIBLE_BORDER);
                component.repaint();
            }

            @Override
            public void focusLost(FocusEvent e) {
                component.setBorder(FOCUS_PLACEHOLDER_BORDER);
                component.repaint();
            }
        });
    }
}

package com.triptracker;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.Border;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import java.awt.*;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.util.HashSet;
import java.util.Set;

/**
 * Swing UI panel for displaying and controlling a Trip.
 * Separated from the Trip data model for clean architecture.
 */
public class TripPanel {
    private static final Color FOCUS_COLOR = new Color(0x5E, 0x9E, 0xD6);
    private static final Border DEFAULT_HEADER_BORDER = new EmptyBorder(5, 7, 5, 7);
    private static final Border FOCUS_HEADER_BORDER = new CompoundBorder(
            new LineBorder(FOCUS_COLOR, 2),
            new EmptyBorder(3, 5, 3, 5)
    );

    private final Trip trip;
    private final JLabel statusLabel = new JLabel();
    private JLabel statsLabel;
    private JLabel summaryPanelTitle;
    private JPanel lootPanel;
    private JPanel headerPanel;
    private Timer statsTimer;
    private Set<String> excludedItems = new HashSet<>();
    private Set<String> excludedNpcs = new HashSet<>();

    public TripPanel(Trip trip) {
        this.trip = trip;
        statusLabel.setBorder(new EmptyBorder(2, 0, 0, 0));
        statusLabel.setFont(FontManager.getRunescapeSmallFont());
        if (trip.getTripStatus()) {
            if (trip.isPaused()) {
                statusLabel.setText("(paused)");
                statusLabel.setForeground(Color.YELLOW);
            } else {
                statusLabel.setText("(active)");
                statusLabel.setForeground(Color.GREEN);
            }
        }
    }

    public JPanel buildHeaderPanel() {
        final JPanel outerPanel = new JPanel();
        outerPanel.setBorder(new EmptyBorder(5, 0, 0, 0));
        outerPanel.setLayout(new BorderLayout());
        outerPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        headerPanel = new JPanel();
        headerPanel.setLayout(new BorderLayout());
        headerPanel.setBackground(ColorScheme.SCROLL_TRACK_COLOR);
        headerPanel.setBorder(new EmptyBorder(5, 7, 5, 7));
        outerPanel.add(headerPanel, BorderLayout.PAGE_START);

        // Content panel: trip name + stats + status
        JPanel contentPanel = new JPanel();
        contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
        contentPanel.setBackground(ColorScheme.SCROLL_TRACK_COLOR);

        summaryPanelTitle = new JLabel(trip.getTripName());
        summaryPanelTitle.setFont(FontManager.getRunescapeBoldFont());
        summaryPanelTitle.setForeground(Color.WHITE);
        summaryPanelTitle.setBorder(new EmptyBorder(0, 0, 3, 0));
        contentPanel.add(summaryPanelTitle);

        // Inline stats: kills | value | gp/hr | duration
        String statsText = getAdjustedKills() + " kills \u2022 " +
                FormatUtil.shortenNumber(getAdjustedTripValue()) + " gp \u2022 " +
                FormatUtil.shortenNumber(getAdjustedGpPerHour()) + " gp/hr \u2022 " +
                trip.calculateTripDuration();
        statsLabel = new JLabel(statsText);
        statsLabel.setFont(FontManager.getRunescapeSmallFont());
        statsLabel.setForeground(Color.WHITE);
        contentPanel.add(statsLabel);

        contentPanel.add(statusLabel);
        headerPanel.add(contentPanel, BorderLayout.CENTER);

        // Right-click context menu on the entire header
        headerPanel.addMouseListener(new java.awt.event.MouseAdapter() {
            public void mousePressed(java.awt.event.MouseEvent evt) {
                if (evt.isPopupTrigger()) {
                    showContextMenu(evt.getX(), evt.getY());
                }
            }

            public void mouseReleased(java.awt.event.MouseEvent evt) {
                if (evt.isPopupTrigger()) {
                    showContextMenu(evt.getX(), evt.getY());
                }
            }

            public void mouseClicked(java.awt.event.MouseEvent evt) {
                if (evt.getButton() == java.awt.event.MouseEvent.BUTTON1) {
                    toggleCollapse();
                }
            }
        });
        headerPanel.setToolTipText("Right-click for options, click to collapse");

        // Make header keyboard-accessible
        headerPanel.setFocusable(true);
        headerPanel.getAccessibleContext().setAccessibleName(trip.getTripName() + " trip panel");
        headerPanel.getAccessibleContext().setAccessibleDescription(
                "Collapsible trip panel. Press Enter or Space to toggle, Shift+F10 for options.");
        headerPanel.addFocusListener(new FocusAdapter() {
            @Override
            public void focusGained(FocusEvent e) {
                headerPanel.setBorder(FOCUS_HEADER_BORDER);
                headerPanel.repaint();
            }

            @Override
            public void focusLost(FocusEvent e) {
                headerPanel.setBorder(DEFAULT_HEADER_BORDER);
                headerPanel.repaint();
            }
        });

        // Keyboard listener for collapse/expand and context menu
        headerPanel.addKeyListener(new java.awt.event.KeyAdapter() {
            @Override
            public void keyPressed(java.awt.event.KeyEvent e) {
                if (e.getKeyCode() == java.awt.event.KeyEvent.VK_ENTER
                        || e.getKeyCode() == java.awt.event.KeyEvent.VK_SPACE) {
                    toggleCollapse();
                    e.consume();
                } else if (e.getKeyCode() == java.awt.event.KeyEvent.VK_F10 && e.isShiftDown()) {
                    e.consume();
                    showContextMenu(0, headerPanel.getHeight());
                }
            }
        });
        headerPanel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        if (trip.getTripStatus() && !trip.isPaused()) {
            startStatsTimer();
        }

        lootPanel = new JPanel();
        lootPanel.setLayout(new BoxLayout(lootPanel, BoxLayout.Y_AXIS));
        outerPanel.add(lootPanel);

        // Restore persisted collapse state
        if (trip.isCollapsed()) {
            lootPanel.setVisible(false);
            summaryPanelTitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            statsLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        }

        return outerPanel;
    }

    private JPopupMenu buildContextMenu() {
        JPopupMenu menu = new JPopupMenu();

        JMenuItem renameItem = new JMenuItem("Rename");
        renameItem.addActionListener(e -> {
            String newName = JOptionPane.showInputDialog(null,
                    "Enter new trip name:", trip.getTripName());
            if (newName != null && !newName.trim().isEmpty()) {
                trip.setTripName(newName.trim());
                summaryPanelTitle.setText(newName.trim());
                trip.getParentPlugin().onTripStatusChanged();
            }
        });
        menu.add(renameItem);

        JMenuItem compareItem = new JMenuItem("Compare...");
        compareItem.addActionListener(e -> trip.getParentPlugin().showTripComparison(trip.getTripId()));
        menu.add(compareItem);

        if (trip.getTripStatus()) {
            if (trip.isPaused()) {
                JMenuItem resumeItem = new JMenuItem("Resume trip");
                resumeItem.addActionListener(e -> resumeTrip());
                menu.add(resumeItem);
            } else {
                JMenuItem pauseItem = new JMenuItem("Pause trip");
                pauseItem.addActionListener(e -> pauseTrip());
                menu.add(pauseItem);
            }

            JMenuItem stopItem = new JMenuItem("Stop trip");
            stopItem.addActionListener(e -> stopTrip());
            menu.add(stopItem);
        } else {
            JMenuItem deleteItem = new JMenuItem("Delete trip");
            deleteItem.addActionListener(e -> deleteTrip());
            menu.add(deleteItem);
        }

        return menu;
    }

    private void showContextMenu(int x, int y) {
        JPopupMenu menu = buildContextMenu();
        menu.show(headerPanel, x, y);
    }

    public void stopTrip() {
        if (trip.getTripStatus()) {
            int selectedOption = JOptionPane.showConfirmDialog(null,
                    "If you end this trip you will not be able to restart it. Are you sure?",
                    "Warning!",
                    JOptionPane.YES_NO_OPTION);

            if (selectedOption == JOptionPane.YES_OPTION) {
                trip.setStatus(false);
                stopStatsTimer();
                updateStats();
                statusLabel.setText("");
                trip.getParentPlugin().onTripStatusChanged();
            }
        }
    }

    public void pauseTrip() {
        if (trip.getTripStatus() && !trip.isPaused()) {
            trip.pause();
            stopStatsTimer();
            statusLabel.setText("(paused)");
            statusLabel.setForeground(Color.YELLOW);
            updateStats();
            trip.getParentPlugin().onTripStatusChanged();
        }
    }

    public void resumeTrip() {
        if (trip.getTripStatus() && trip.isPaused()) {
            trip.resume();
            startStatsTimer();
            statusLabel.setText("(active)");
            statusLabel.setForeground(Color.GREEN);
            updateStats();
            trip.getParentPlugin().onTripStatusChanged();
        }
    }

    public void deleteTrip() {
        int selectedOption = JOptionPane.showConfirmDialog(null,
                "If you delete this trip you will permanently lose its data. Are you sure?",
                "Warning!",
                JOptionPane.YES_NO_OPTION);

        if (selectedOption == JOptionPane.YES_OPTION) {
            stopStatsTimer();
            trip.getParentPlugin().removeTrip(trip.getTripName());
        }
    }

    public void setStatus(boolean status) {
        if (!status) {
            stopStatsTimer();
            statusLabel.setText("");
        } else {
            if (trip.isPaused()) {
                statusLabel.setText("(paused)");
                statusLabel.setForeground(Color.YELLOW);
            } else {
                statusLabel.setText("(active)");
                statusLabel.setForeground(Color.GREEN);
                startStatsTimer();
            }
        }
    }

    public void addLootPanel(JPanel panel) {
        this.lootPanel.add(panel, 0);
        this.lootPanel.revalidate();
        this.lootPanel.repaint();
        updateStats();
    }

    /**
     * Refreshes the inline stats label with current trip data.
     */
    public void updateStats() {
        if (statsLabel != null) {
            String statsText = getAdjustedKills() + " kills \u2022 " +
                    FormatUtil.shortenNumber(getAdjustedTripValue()) + " gp \u2022 " +
                    FormatUtil.shortenNumber(getAdjustedGpPerHour()) + " gp/hr \u2022 " +
                    trip.calculateTripDuration();
            statsLabel.setText(statsText);
        }
    }

    private void startStatsTimer() {
        if (statsTimer == null) {
            statsTimer = new Timer(1000, e -> updateStats());
            statsTimer.start();
        }
    }

    private void stopStatsTimer() {
        if (statsTimer != null) {
            statsTimer.stop();
            statsTimer = null;
        }
    }

    public JPanel getLootPanel() {
        return lootPanel;
    }

    private void toggleCollapse() {
        if (lootPanel.isVisible()) {
            lootPanel.setVisible(false);
            summaryPanelTitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            statsLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            trip.setCollapsed(true);
        } else {
            lootPanel.setVisible(true);
            summaryPanelTitle.setForeground(Color.WHITE);
            statsLabel.setForeground(Color.WHITE);
            trip.setCollapsed(false);
        }
        trip.getParentPlugin().onTripStatusChanged();
    }

    public Trip getTrip() {
        return trip;
    }

    /**
     * Programmatically set the collapsed state without triggering a full panel rebuild.
     */
    public void setCollapsedState(boolean collapsed) {
        if (collapsed) {
            lootPanel.setVisible(false);
            summaryPanelTitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            statsLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        } else {
            lootPanel.setVisible(true);
            summaryPanelTitle.setForeground(Color.WHITE);
            statsLabel.setForeground(Color.WHITE);
        }
        trip.setCollapsed(collapsed);
    }

    public void setExcludedItems(Set<String> excludedItems) {
        this.excludedItems = excludedItems != null ? excludedItems : new HashSet<>();
    }

    public void setExcludedNpcs(Set<String> excludedNpcs) {
        this.excludedNpcs = excludedNpcs != null ? excludedNpcs : new HashSet<>();
    }

    private long getAdjustedTripValue() {
        if (excludedItems.isEmpty() && excludedNpcs.isEmpty()) {
            return trip.getTripValue();
        }
        long excluded = 0;
        for (NpcLootAggregate agg : trip.getTripAggregates()) {
            if (excludedNpcs.contains(agg.getNpcName().toLowerCase().trim())) {
                for (TrackableDroppedItem item : agg.getDroppedItems()) {
                    excluded += item.getTotalGePrice();
                }
            } else {
                for (TrackableDroppedItem item : agg.getDroppedItems()) {
                    if (excludedItems.contains(item.getItemName().toLowerCase().trim())) {
                        excluded += item.getTotalGePrice();
                    }
                }
            }
        }
        return trip.getTripValue() - excluded;
    }

    private int getAdjustedKills() {
        if (excludedNpcs.isEmpty()) {
            return trip.getTripKills();
        }
        int excluded = 0;
        for (NpcLootAggregate agg : trip.getTripAggregates()) {
            if (excludedNpcs.contains(agg.getNpcName().toLowerCase().trim())) {
                excluded += agg.getNumberOfKills();
            }
        }
        return trip.getTripKills() - excluded;
    }

    private long getAdjustedGpPerHour() {
        long adjustedValue = getAdjustedTripValue();
        long durationSeconds = trip.getDurationSeconds();
        if (durationSeconds <= 0) {
            return 0;
        }
        return (adjustedValue * 3600L) / durationSeconds;
    }
}

package com.triptracker;

import net.runelite.client.game.ItemManager;

import java.util.ArrayList;
import java.util.List;

/**
 * A serializable record of a trip.
 * This is the JSON-friendly representation of Trip + its associated drops.
 */
public class TripRecord {
    String tripName;
    boolean tripActive;
    boolean tripPaused;
    boolean collapsed;
    long tripStartTimeEpoch;
    String tripStartTime;
    String tripEndTime;
    long tripEndTimeEpoch;
    int tripKills;
    long tripValue;
    int tripId;
    long pausedDurationMs;
    long pausedAtEpoch;
    List<NpcAggregateRecord> npcAggregates;

    public static TripRecord fromTrip(Trip trip) {
        TripRecord record = new TripRecord();
        record.tripName = trip.getTripName();
        record.tripActive = trip.getTripStatus();
        record.tripPaused = trip.isPaused();
        record.collapsed = trip.isCollapsed();
        record.tripStartTimeEpoch = trip.getTripStartTimeEpoch();
        record.tripStartTime = trip.getTripStartTime();
        record.tripEndTime = trip.getTripEndTime();
        record.tripEndTimeEpoch = trip.getTripEndTimeEpoch();
        record.tripKills = trip.getTripKills();
        record.tripValue = trip.getTripValue();
        record.tripId = trip.getTripId();
        record.pausedDurationMs = trip.getPausedDurationMs();
        record.pausedAtEpoch = trip.getPausedAtEpoch();
        record.npcAggregates = new ArrayList<>();

        for (NpcLootAggregate aggregate : trip.getTripAggregates()) {
            NpcAggregateRecord aggRecord = new NpcAggregateRecord();
            aggRecord.npcName = aggregate.getNpcName();
            aggRecord.numberOfKills = aggregate.getNumberOfKills();
            aggRecord.lastKillTime = aggregate.getLastKillTime();
            aggRecord.collapsed = aggregate.collapsed;
            aggRecord.items = new ArrayList<>();

            for (TrackableDroppedItem item : aggregate.getDroppedItems()) {
                DropRecord.ItemRecord itemRecord = new DropRecord.ItemRecord();
                itemRecord.itemId = item.getItemId();
                itemRecord.itemName = item.getItemName();
                itemRecord.quantity = item.getQuantity();
                itemRecord.gePrice = item.getTotalGePrice() / Math.max(item.getQuantity(), 1);
                itemRecord.haPrice = item.getTotalHaPrice() / Math.max(item.getQuantity(), 1);
                aggRecord.items.add(itemRecord);
            }

            record.npcAggregates.add(aggRecord);
        }

        return record;
    }

    /**
     * Reconstruct a Trip from this record.
     */
    public Trip toTrip(EnhancedLootTrackerPlugin plugin, ItemManager itemManager) {
        Trip trip = new Trip(tripName, plugin, tripActive, tripStartTimeEpoch,
                tripStartTime, tripEndTime, tripEndTimeEpoch, tripKills, tripValue, tripId, collapsed,
                tripPaused, pausedDurationMs, pausedAtEpoch);

        if (npcAggregates == null) {
            return trip;
        }

        for (NpcAggregateRecord aggRecord : npcAggregates) {
            if (aggRecord == null || aggRecord.npcName == null) {
                continue;
            }

            NpcLootAggregate aggregate = new NpcLootAggregate(aggRecord.npcName, itemManager);

            // Restore items into the aggregate
            if (aggRecord.items != null) {
                for (DropRecord.ItemRecord itemRecord : aggRecord.items) {
                    if (itemRecord == null) {
                        continue;
                    }
                    TrackableDroppedItem item = new TrackableDroppedItem(
                            itemRecord.itemId, itemRecord.itemName,
                            itemRecord.quantity, itemRecord.gePrice, itemRecord.haPrice);
                    aggregate.getDroppedItems().add(item);
                }
            }

            // Strip farming-excluded items from legacy farming-sourced aggregates
            plugin.stripFarmingExcludedItemsFromAggregate(aggregate);

            // Restore kill count and last kill time directly
            aggregate.numberOfKills = aggRecord.numberOfKills;
            aggregate.lastKillTime = aggRecord.lastKillTime;
            aggregate.collapsed = aggRecord.collapsed;
            // Rebuild the aggregation map from the restored items
            aggregate.rebuildAggregationMap();

            trip.addNpcAggregateToTrip(aggregate);
        }

        return trip;
    }

    /**
     * Record for a single NPC's aggregated loot within a trip.
     */
    public static class NpcAggregateRecord {
        String npcName;
        int numberOfKills;
        String lastKillTime;
        boolean collapsed;
        List<DropRecord.ItemRecord> items;
    }
}

package com.triptracker;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

import java.io.File;
import java.io.IOException;
import java.lang.reflect.Type;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

/**
 * Handles reading and writing trip data to disk.
 * Data is stored as JSON in ~/.runelite/trip-tracker/
 * Writes are performed asynchronously on a background thread to avoid blocking the game thread.
 *
 * File naming convention:
 * - v0 (legacy): trips.json, drops.json (bare arrays, no version field)
 * - v1+: trips.v1.json, drops.v1.json (object envelope with "version" field)
 *
 * On load, the highest available version file is used. Old files are never deleted,
 * serving as backups if a user needs to roll back.
 */
@Slf4j
public class TripStorageService {

    private static final String PLUGIN_DIR_NAME = "trip-tracker";
    private static final String COLLAPSED_NPCS_FILE_NAME = "collapsed-npcs.json";

    // Current schema version — increment when making structural changes to the persisted format
    static final int CURRENT_VERSION = 1;

    // Base names (without extension) for versioned files
    private static final String TRIPS_BASE = "trips";
    private static final String DROPS_BASE = "drops";

    private final Gson gson;
    private final File baseDir; // Root plugin directory (~/.runelite/trip-tracker/)
    private File pluginDir;     // Active data directory (baseDir or baseDir/{accountHash}/)
    private final ExecutorService writeExecutor;
    private volatile boolean writesDisabled;

    public TripStorageService(Gson clientGson) {
        this(clientGson, new File(RuneLite.RUNELITE_DIR, PLUGIN_DIR_NAME));
    }

    public TripStorageService(Gson clientGson, File pluginDir) {
        this.gson = clientGson.newBuilder().setPrettyPrinting().create();
        this.baseDir = pluginDir;
        this.pluginDir = pluginDir;
        this.writeExecutor = Executors.newSingleThreadExecutor(r -> {
            Thread t = new Thread(r, "trip-tracker-persistence");
            t.setDaemon(true);
            return t;
        });

        if (!pluginDir.exists()) {
            pluginDir.mkdirs();
        }
    }

    // --- Account switching ---

    /**
     * Switches the active data directory to a character-specific subdirectory.
     * If legacy files exist in the root dir but the account subdir is empty,
     * copies them into the account subdir (one-time migration).
     *
     * @param accountHash the account's unique hash from client.getAccountHash()
     */
    public void switchAccount(long accountHash) {
        File accountDir = new File(baseDir, String.valueOf(accountHash));
        if (!accountDir.exists()) {
            accountDir.mkdirs();
        }

        // One-time migration: if the account dir has no data files but the base dir does,
        // copy them over (first login with character-specific tracking enabled)
        migrateIfNeeded(accountDir);

        this.pluginDir = accountDir;
        log.debug("Switched storage to account directory: {}", accountDir.getAbsolutePath());
    }

    /**
     * Returns the currently active data directory.
     */
    public File getActiveDirectory() {
        return pluginDir;
    }

    /**
     * Copies legacy data files from the base directory to the account directory
     * if the account directory has no versioned data files yet.
     */
    private void migrateIfNeeded(File accountDir) {
        // Check if the account dir already has data (any version of drops or trips)
        boolean hasDrops = false;
        boolean hasTrips = false;
        for (int v = CURRENT_VERSION; v >= 0; v--) {
            if (new File(accountDir, versionedFileName(DROPS_BASE, v)).exists()) {
                hasDrops = true;
            }
            if (new File(accountDir, versionedFileName(TRIPS_BASE, v)).exists()) {
                hasTrips = true;
            }
        }

        if (hasDrops || hasTrips) {
            // Account already has data — no migration needed
            return;
        }

        // Check if legacy files exist in the base directory
        String[] filesToMigrate = {
                versionedFileName(DROPS_BASE, CURRENT_VERSION),
                versionedFileName(DROPS_BASE, 0),
                versionedFileName(TRIPS_BASE, CURRENT_VERSION),
                versionedFileName(TRIPS_BASE, 0),
                COLLAPSED_NPCS_FILE_NAME,
                SESSION_FILE_NAME
        };

        boolean migrated = false;
        for (String fileName : filesToMigrate) {
            File source = new File(baseDir, fileName);
            if (source.exists()) {
                File dest = new File(accountDir, fileName);
                try {
                    Files.copy(source.toPath(), dest.toPath());
                    migrated = true;
                    log.debug("Migrated {} to account directory", fileName);
                } catch (IOException e) {
                    log.warn("Failed to migrate {} to account directory", fileName, e);
                }
            }
        }

        if (migrated) {
            log.info("Migrated existing tracking data to character-specific directory: {}", accountDir.getName());
        }
    }

    // --- File naming helpers ---

    /**
     * Returns the filename for a given base and version.
     * v0 (legacy) uses "base.json", v1+ uses "base.v{N}.json".
     */
    private static String versionedFileName(String base, int version) {
        if (version == 0) {
            return base + ".json";
        }
        return base + ".v" + version + ".json";
    }

    /**
     * Finds the highest version file that exists on disk for the given base name.
     * Scans from CURRENT_VERSION down to 0. Returns null if no file exists.
     */
    private String findHighestVersionFile(String base) {
        for (int v = CURRENT_VERSION; v >= 0; v--) {
            String fileName = versionedFileName(base, v);
            File file = new File(pluginDir, fileName);
            if (file.exists()) {
                return fileName;
            }
        }
        return null;
    }

    // --- Trips ---

    /**
     * Save trip data to disk asynchronously.
     */
    public void saveTrips(List<Trip> trips) {
        if (writesDisabled) {
            return;
        }
        List<TripRecord> records = new ArrayList<>();
        for (Trip trip : trips) {
            records.add(TripRecord.fromTrip(trip));
        }

        writeExecutor.submit(() -> {
            JsonObject envelope = new JsonObject();
            envelope.addProperty("version", CURRENT_VERSION);
            envelope.add("trips", gson.toJsonTree(records));
            writeFile(versionedFileName(TRIPS_BASE, CURRENT_VERSION), gson.toJson(envelope));
        });
    }

    /**
     * Save trip data synchronously (shutdown / account switch). Won't overwrite a non-empty
     * file with an empty list; for an intentional clear use {@link #saveTripsSync(List, boolean)}.
     */
    public void saveTripsSync(List<Trip> trips) {
        saveTripsSync(trips, false);
    }

    /**
     * @param allowEmpty false refuses to overwrite a non-empty trips file with an empty list
     *                   (see #26); pass true only when the empty result is intentional (deletion).
     */
    public void saveTripsSync(List<Trip> trips, boolean allowEmpty) {
        List<TripRecord> records = new ArrayList<>();
        for (Trip trip : trips) {
            records.add(TripRecord.fromTrip(trip));
        }

        if (!allowEmpty && records.isEmpty() && !loadTrips().isEmpty()) {
            log.warn("Refusing to overwrite non-empty trips file with empty data (see #26)");
            return;
        }

        JsonObject envelope = new JsonObject();
        envelope.addProperty("version", CURRENT_VERSION);
        envelope.add("trips", gson.toJsonTree(records));
        writeFile(versionedFileName(TRIPS_BASE, CURRENT_VERSION), gson.toJson(envelope));
    }

    /**
     * Load trip data from disk.
     * Scans from highest version down to legacy. Handles bare arrays (v0) and versioned envelopes (v1+).
     */
    public List<TripRecord> loadTrips() {
        String fileName = findHighestVersionFile(TRIPS_BASE);
        if (fileName == null) {
            return new ArrayList<>();
        }

        String json = readFile(fileName);
        if (json == null || json.isEmpty()) {
            return new ArrayList<>();
        }

        try {
            JsonElement root = gson.fromJson(json, JsonElement.class);
            JsonArray tripsArray;

            if (root.isJsonObject()) {
                JsonObject obj = root.getAsJsonObject();
                int version = obj.has("version") ? obj.get("version").getAsInt() : 0;
                log.debug("Loading {} (version {})", fileName, version);
                // Future migrations: if (version < 2) { migrateTripsV1toV2(obj); }
                tripsArray = obj.has("trips") ? obj.getAsJsonArray("trips") : new JsonArray();
            } else if (root.isJsonArray()) {
                log.debug("Loading {} (legacy format, no version)", fileName);
                tripsArray = root.getAsJsonArray();
            } else {
                log.warn("Unexpected format in {}, starting fresh", fileName);
                return new ArrayList<>();
            }

            Type listType = new TypeToken<ArrayList<TripRecord>>() {}.getType();
            List<TripRecord> records = gson.fromJson(tripsArray, listType);
            return records != null ? records : new ArrayList<>();
        } catch (Exception e) {
            log.warn("Failed to parse trip data from {}, starting fresh", fileName, e);
            return new ArrayList<>();
        }
    }

    // --- Drops ---

    /**
     * Save the list-view drop history to disk asynchronously.
     */
    public void saveDrops(List<TrackableItemDrop> drops) {
        if (writesDisabled) {
            return;
        }
        List<DropRecord> records = new ArrayList<>();
        for (TrackableItemDrop drop : drops) {
            records.add(DropRecord.fromDrop(drop));
        }

        writeExecutor.submit(() -> {
            JsonObject envelope = new JsonObject();
            envelope.addProperty("version", CURRENT_VERSION);
            envelope.add("drops", gson.toJsonTree(records));
            writeFile(versionedFileName(DROPS_BASE, CURRENT_VERSION), gson.toJson(envelope));
        });
    }

    /**
     * Save the list-view drop history synchronously (shutdown / account switch). Won't overwrite
     * a non-empty file with an empty list; for an intentional clear use the two-arg overload.
     */
    public void saveDropsSync(List<TrackableItemDrop> drops) {
        saveDropsSync(drops, false);
    }

    /**
     * @param allowEmpty false refuses to overwrite a non-empty drops file with an empty list
     *                   (see #26); pass true only when the empty result is intentional.
     */
    public void saveDropsSync(List<TrackableItemDrop> drops, boolean allowEmpty) {
        List<DropRecord> records = new ArrayList<>();
        for (TrackableItemDrop drop : drops) {
            records.add(DropRecord.fromDrop(drop));
        }

        if (!allowEmpty && records.isEmpty() && !loadDrops().isEmpty()) {
            log.warn("Refusing to overwrite non-empty drops file with empty data (see #26)");
            return;
        }

        JsonObject envelope = new JsonObject();
        envelope.addProperty("version", CURRENT_VERSION);
        envelope.add("drops", gson.toJsonTree(records));
        writeFile(versionedFileName(DROPS_BASE, CURRENT_VERSION), gson.toJson(envelope));
    }

    /**
     * Load the list-view drop history from disk.
     * Scans from highest version down to legacy. Handles bare arrays (v0) and versioned envelopes (v1+).
     */
    public List<DropRecord> loadDrops() {
        String fileName = findHighestVersionFile(DROPS_BASE);
        if (fileName == null) {
            return new ArrayList<>();
        }

        String json = readFile(fileName);
        if (json == null || json.isEmpty()) {
            return new ArrayList<>();
        }

        try {
            JsonElement root = gson.fromJson(json, JsonElement.class);
            JsonArray dropsArray;

            if (root.isJsonObject()) {
                JsonObject obj = root.getAsJsonObject();
                int version = obj.has("version") ? obj.get("version").getAsInt() : 0;
                log.debug("Loading {} (version {})", fileName, version);
                // Future migrations: if (version < 2) { migrateDropsV1toV2(obj); }
                dropsArray = obj.has("drops") ? obj.getAsJsonArray("drops") : new JsonArray();
            } else if (root.isJsonArray()) {
                log.debug("Loading {} (legacy format, no version)", fileName);
                dropsArray = root.getAsJsonArray();
            } else {
                log.warn("Unexpected format in {}, starting fresh", fileName);
                return new ArrayList<>();
            }

            Type listType = new TypeToken<ArrayList<DropRecord>>() {}.getType();
            List<DropRecord> records = gson.fromJson(dropsArray, listType);
            return records != null ? records : new ArrayList<>();
        } catch (Exception e) {
            log.warn("Failed to parse drop data from {}, starting fresh", fileName, e);
            return new ArrayList<>();
        }
    }

    // --- Session timestamp ---

    private static final String SESSION_FILE_NAME = "last-session.txt";

    /**
     * Persist the epoch timestamp of the last logout or shutdown.
     * Written synchronously since it's called during shutdown and logout.
     */
    public void saveLastSessionEpoch(long epochMs) {
        writeFile(SESSION_FILE_NAME, String.valueOf(epochMs));
    }

    /**
     * Load the last session epoch. Returns 0 if not found.
     */
    public long loadLastSessionEpoch() {
        String content = readFile(SESSION_FILE_NAME);
        if (content == null || content.trim().isEmpty()) {
            return 0;
        }
        try {
            return Long.parseLong(content.trim());
        } catch (NumberFormatException e) {
            log.warn("Failed to parse last session epoch, returning 0");
            return 0;
        }
    }

    // --- Collapsed NPCs ---

    /**
     * Save the set of collapsed NPC names (for grouped view) to disk asynchronously.
     */
    public void saveCollapsedNpcs(Set<String> collapsedNpcs) {
        if (writesDisabled) {
            return;
        }
        Set<String> snapshot = new HashSet<>(collapsedNpcs);
        writeExecutor.submit(() -> {
            String json = gson.toJson(snapshot);
            writeFile(COLLAPSED_NPCS_FILE_NAME, json);
        });
    }

    /**
     * Load the set of collapsed NPC names from disk.
     */
    public Set<String> loadCollapsedNpcs() {
        String json = readFile(COLLAPSED_NPCS_FILE_NAME);
        if (json == null || json.isEmpty()) {
            return new HashSet<>();
        }

        try {
            Type setType = new TypeToken<HashSet<String>>() {}.getType();
            Set<String> result = gson.fromJson(json, setType);
            return result != null ? result : new HashSet<>();
        } catch (Exception e) {
            log.warn("Failed to parse collapsed NPC data from disk, starting fresh", e);
            return new HashSet<>();
        }
    }

    // --- Lifecycle ---

    /**
     * Waits for any pending async writes to complete without shutting down the executor.
     * Call before a sync save to ensure no stale async write overwrites it.
     */
    public void drainPendingWrites() {
        try {
            // Submit a no-op and wait for it — since the executor is single-threaded,
            // this guarantees all previously-submitted writes have completed.
            writeExecutor.submit(() -> {}).get(5, TimeUnit.SECONDS);
        } catch (Exception e) {
            log.warn("Failed to drain pending writes", e);
        }
    }

    /**
     * Immediately shut down the write executor, discarding any pending writes.
     * Use after a sync save to prevent stale async writes from overwriting it.
     */
    public void shutdownNow() {
        writeExecutor.shutdownNow();
    }

    /**
     * Shutdown the write executor, waiting for pending writes to complete.
     */
    public void shutdown() {
        writesDisabled = true;
        writeExecutor.shutdown();
        try {
            if (!writeExecutor.awaitTermination(5, TimeUnit.SECONDS)) {
                log.warn("Persistence executor did not terminate in time");
                writeExecutor.shutdownNow();
            }
        } catch (InterruptedException e) {
            log.warn("Interrupted while waiting for persistence executor shutdown");
            writeExecutor.shutdownNow();
        }
    }

    // --- File I/O helpers ---

    private void writeFile(String fileName, String content) {
        try {
            Path filePath = new File(pluginDir, fileName).toPath();
            Files.writeString(filePath, content);
            log.debug("Saved data to {}", filePath);
        } catch (IOException e) {
            log.error("Failed to write {}", fileName, e);
        }
    }

    private String readFile(String fileName) {
        File file = new File(pluginDir, fileName);
        if (!file.exists()) {
            return null;
        }

        try {
            return Files.readString(file.toPath());
        } catch (IOException e) {
            log.error("Failed to read {}", fileName, e);
            return null;
        }
    }
}

package com.triptracker;

import org.junit.Before;
import org.junit.Test;

import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import java.awt.Component;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Covers the trip-selection checklist filter in {@link TripComparisonPanel}.
 *
 * The filter is a VIEW over which checkboxes are shown; it must never mutate
 * {@code selectedTripIds}. These tests assert on panel state (which checkboxes
 * are present, their labels and selected flag, and the empty-state label) rather
 * than Swing rendering, per the testing standards.
 */
public class ComparisonFilterTest {

    private EnhancedLootTrackerPlugin mockPlugin;
    private List<Trip> trips;
    private TripComparisonPanel panel;

    @Before
    public void setUp() throws Exception {
        mockPlugin = mock(EnhancedLootTrackerPlugin.class);

        AtomicInteger idSeq = new AtomicInteger(1);
        when(mockPlugin.getNextTripNumber()).thenAnswer(inv -> idSeq.getAndIncrement());
        when(mockPlugin.getExcludedItems()).thenReturn(new HashSet<>());
        when(mockPlugin.getExcludedNpcs()).thenReturn(new HashSet<>());

        Trip guards1 = new Trip("Guards 1", mockPlugin);
        Trip guards2 = new Trip("Guards 2", mockPlugin);
        Trip vorkath = new Trip("Vorkath", mockPlugin);
        Trip zulrah = new Trip("Zulrah", mockPlugin);
        trips = new ArrayList<>(Arrays.asList(guards1, guards2, vorkath, zulrah));

        final int preSelected = guards1.getTripId();
        onEdt(() -> panel = new TripComparisonPanel(trips, preSelected, () -> {}, mockPlugin));
    }

    @Test
    public void noFilterShowsAllTrips() throws Exception {
        List<String> labels = checkboxLabels();
        assertEquals(trips.size(), labels.size());
        assertTrue(labels.containsAll(Arrays.asList("Guards 1", "Guards 2", "Vorkath", "Zulrah")));
    }

    @Test
    public void substringMatchIsCaseInsensitive() throws Exception {
        applyFilter("guards");

        List<String> labels = checkboxLabels();
        assertEquals(2, labels.size());
        assertTrue(labels.containsAll(Arrays.asList("Guards 1", "Guards 2")));
    }

    @Test
    public void noMatchShowsEmptyStateLabel() throws Exception {
        applyFilter("zzz");

        assertEquals(0, checkboxLabels().size());
        assertTrue("Expected a 'No trips match' label when nothing matches", hasNoMatchLabel());
    }

    @Test
    public void clearingFilterRestoresFullList() throws Exception {
        applyFilter("guards");
        assertEquals(2, checkboxLabels().size());

        applyFilter("");
        assertEquals(trips.size(), checkboxLabels().size());
        assertFalse(hasNoMatchLabel());
    }

    @Test
    public void selectionPersistsWhenTripIsFilteredOutThenBackIn() throws Exception {
        // Pre-select Zulrah via the selection set (the single source of truth).
        int zulrahId = trips.get(3).getTripId();
        addSelectedId(zulrahId);

        // Filter Zulrah out of view.
        applyFilter("guards");
        assertFalse("Zulrah checkbox should be hidden by the filter", checkboxLabels().contains("Zulrah"));

        // The selection must survive even though the checkbox is not shown.
        assertTrue("Filtered-out trip must stay selected", selectedTripIds().contains(zulrahId));

        // Clear the filter: Zulrah comes back, still checked.
        applyFilter("");
        JCheckBox zulrahBox = checkboxByLabel("Zulrah");
        assertNotNull(zulrahBox);
        assertTrue("Re-shown checkbox must reflect selectedTripIds", zulrahBox.isSelected());
    }

    @Test
    public void checkboxReflectsSelectionWhenReShown() throws Exception {
        int vorkathId = trips.get(2).getTripId();
        addSelectedId(vorkathId);

        applyFilter("zulrah");
        assertNull(checkboxByLabel("Vorkath"));
        assertTrue(selectedTripIds().contains(vorkathId));

        applyFilter("vork");
        JCheckBox vorkBox = checkboxByLabel("Vorkath");
        assertNotNull(vorkBox);
        assertTrue(vorkBox.isSelected());
    }

    // === Filter-aware All / None ===

    @Test
    public void selectAllVisibleWithFilterActive() throws Exception {
        int guards1 = trips.get(0).getTripId();
        int guards2 = trips.get(1).getTripId();
        int zulrahId = trips.get(3).getTripId();

        // A selected trip that the filter will hide.
        addSelectedId(zulrahId);

        applyFilter("guards");
        selectVisible();

        Set<Integer> ids = selectedTripIds();
        assertTrue("Visible 'Guards 1' should be selected", ids.contains(guards1));
        assertTrue("Visible 'Guards 2' should be selected", ids.contains(guards2));
        assertTrue("Filtered-out 'Zulrah' must stay selected", ids.contains(zulrahId));
    }

    @Test
    public void deselectAllVisibleWithFilterActive() throws Exception {
        int guards1 = trips.get(0).getTripId();
        int guards2 = trips.get(1).getTripId();
        int vorkathId = trips.get(2).getTripId();
        int zulrahId = trips.get(3).getTripId();

        // Select every trip, then filter to a subset and deselect-visible.
        addSelectedId(guards1);
        addSelectedId(guards2);
        addSelectedId(vorkathId);
        addSelectedId(zulrahId);

        applyFilter("guards");
        deselectVisible();

        Set<Integer> ids = selectedTripIds();
        assertFalse("Visible 'Guards 1' should be deselected", ids.contains(guards1));
        assertFalse("Visible 'Guards 2' should be deselected", ids.contains(guards2));
        assertTrue("Filtered-out 'Vorkath' must stay selected", ids.contains(vorkathId));
        assertTrue("Filtered-out 'Zulrah' must stay selected", ids.contains(zulrahId));
    }

    @Test
    public void noFilterSelectAllThenNoneHasNoRegression() throws Exception {
        // No filter: All selects every trip, None clears every selection.
        applyFilter("");
        selectVisible();

        Set<Integer> all = new HashSet<>();
        for (Trip t : trips) {
            all.add(t.getTripId());
        }
        assertEquals("All (no filter) should select every trip", all, selectedTripIds());

        deselectVisible();
        assertTrue("None (no filter) should clear every selection", selectedTripIds().isEmpty());
    }

    @Test
    public void workedExampleSelectionPersistsAcrossFilterAndButtons() throws Exception {
        int guards1 = trips.get(0).getTripId();
        int guards2 = trips.get(1).getTripId();
        int vorkathId = trips.get(2).getTripId();
        int zulrahId = trips.get(3).getTripId();

        // Pre-select a trip that will be filtered out (the "Zulrah" in the example).
        addSelectedId(zulrahId);

        // Filter to the matching subset and select everything visible.
        applyFilter("guards");
        selectVisible();

        Set<Integer> afterSelect = selectedTripIds();
        assertTrue(afterSelect.contains(guards1));
        assertTrue(afterSelect.contains(guards2));
        assertTrue("Pre-selected filtered-out trip stays selected", afterSelect.contains(zulrahId));
        assertFalse("Non-matching 'Vorkath' not selected", afterSelect.contains(vorkathId));

        // Deselect everything visible: only the Guards go, Zulrah stays.
        deselectVisible();
        Set<Integer> afterDeselect = selectedTripIds();
        assertFalse(afterDeselect.contains(guards1));
        assertFalse(afterDeselect.contains(guards2));
        assertTrue("Filtered-out 'Zulrah' still selected", afterDeselect.contains(zulrahId));

        // Clear the filter: Guards render unchecked, Zulrah checked, Vorkath unchecked.
        applyFilter("");
        assertFalse(checkboxByLabel("Guards 1").isSelected());
        assertFalse(checkboxByLabel("Guards 2").isSelected());
        assertTrue(checkboxByLabel("Zulrah").isSelected());
        assertFalse(checkboxByLabel("Vorkath").isSelected());
    }

    // === Helpers ===

    /**
     * Mirrors the "All" button handler: on the EDT, for every trip matching the
     * active filter (via the panel's private {@code matchesFilter}), add its id.
     */
    private void selectVisible() throws Exception {
        onEdt(() -> {
            try {
                Set<Integer> ids = selectedTripIds();
                for (Trip trip : trips) {
                    if (matchesFilter(trip)) {
                        ids.add(trip.getTripId());
                    }
                }
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
    }

    /**
     * Mirrors the "None" button handler: on the EDT, for every trip matching the
     * active filter, remove its id (never clear()).
     */
    private void deselectVisible() throws Exception {
        onEdt(() -> {
            try {
                Set<Integer> ids = selectedTripIds();
                for (Trip trip : trips) {
                    if (matchesFilter(trip)) {
                        ids.remove(trip.getTripId());
                    }
                }
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
    }

    private boolean matchesFilter(Trip trip) throws Exception {
        Method m = findMethod(panel.getClass(), "matchesFilter", Trip.class);
        m.setAccessible(true);
        return (Boolean) m.invoke(panel, trip);
    }

    /**
     * Sets filterText directly and invokes rebuildChecklist() on the EDT, bypassing
     * the debounce timer so the view updates synchronously and deterministically.
     */
    private void applyFilter(String text) throws Exception {
        onEdt(() -> {
            try {
                setField(panel, "filterText", text.trim().toLowerCase());
                invokePrivate(panel, "rebuildChecklist");
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
    }

    private void addSelectedId(int id) throws Exception {
        @SuppressWarnings("unchecked")
        Set<Integer> ids = (Set<Integer>) getField(panel, "selectedTripIds");
        ids.add(id);
    }

    @SuppressWarnings("unchecked")
    private Set<Integer> selectedTripIds() throws Exception {
        return (Set<Integer>) getField(panel, "selectedTripIds");
    }

    private JPanel checklistPanel() throws Exception {
        return (JPanel) getField(panel, "checklistPanel");
    }

    private List<String> checkboxLabels() throws Exception {
        List<String> labels = new ArrayList<>();
        for (Component c : checklistPanel().getComponents()) {
            if (c instanceof JCheckBox) {
                labels.add(((JCheckBox) c).getText());
            }
        }
        return labels;
    }

    private JCheckBox checkboxByLabel(String label) throws Exception {
        for (Component c : checklistPanel().getComponents()) {
            if (c instanceof JCheckBox && label.equals(((JCheckBox) c).getText())) {
                return (JCheckBox) c;
            }
        }
        return null;
    }

    private boolean hasNoMatchLabel() throws Exception {
        for (Component c : checklistPanel().getComponents()) {
            if (c instanceof JLabel && "No trips match".equals(((JLabel) c).getText())) {
                return true;
            }
        }
        return false;
    }

    private void onEdt(Runnable r) throws Exception {
        SwingUtilities.invokeAndWait(r);
    }

    private void invokePrivate(Object target, String methodName) throws Exception {
        Method m = findMethod(target.getClass(), methodName);
        m.setAccessible(true);
        m.invoke(target);
    }

    private Object getField(Object target, String fieldName) throws Exception {
        Field f = findField(target.getClass(), fieldName);
        f.setAccessible(true);
        return f.get(target);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field f = findField(target.getClass(), fieldName);
        f.setAccessible(true);
        f.set(target, value);
    }

    private Field findField(Class<?> clazz, String fieldName) throws NoSuchFieldException {
        while (clazz != null) {
            try {
                return clazz.getDeclaredField(fieldName);
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            }
        }
        throw new NoSuchFieldException(fieldName);
    }

    private Method findMethod(Class<?> clazz, String methodName) throws NoSuchMethodException {
        while (clazz != null) {
            try {
                return clazz.getDeclaredMethod(methodName);
            } catch (NoSuchMethodException e) {
                clazz = clazz.getSuperclass();
            }
        }
        throw new NoSuchMethodException(methodName);
    }

    private Method findMethod(Class<?> clazz, String methodName, Class<?>... paramTypes) throws NoSuchMethodException {
        while (clazz != null) {
            try {
                return clazz.getDeclaredMethod(methodName, paramTypes);
            } catch (NoSuchMethodException e) {
                clazz = clazz.getSuperclass();
            }
        }
        throw new NoSuchMethodException(methodName);
    }
}

package com.triptracker;

import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPCComposition;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.ui.ClientToolbar;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.*;

/**
 * Tests the save and shutdown sequence logic.
 *
 * Key invariants tested:
 * 1. Each drop triggers an immediate async save.
 * 2. Multiple rapid drops each trigger their own save.
 * 3. Shutdown performs a sync save with all current data (when data was loaded this session).
 * 4. Shutdown skips sync save when no account is loaded.
 * 5. Shutdown skips sync save when data was never loaded this session (bug #26 race guard).
 * 6. Shutdown cancels farming/bird-nest debounce timers.
 * 7. Save data contains the correct number of drops.
 */
public class DebounceSaveShutdownTest {

    private EnhancedLootTrackerPlugin plugin;
    private TripStorageService mockStorageService;
    private ScheduledExecutorService executor;
    private Client mockClient;
    private ItemManager mockItemManager;
    private EnhancedLootTrackerPanel mockPanel;

    @Before
    public void setUp() throws Exception {
        plugin = new EnhancedLootTrackerPlugin();
        mockClient = mock(Client.class);
        mockItemManager = mock(ItemManager.class);
        mockPanel = mock(EnhancedLootTrackerPanel.class);
        mockStorageService = mock(TripStorageService.class);

        ItemComposition mockComposition = mock(ItemComposition.class);
        when(mockItemManager.getItemComposition(anyInt())).thenReturn(mockComposition);
        when(mockItemManager.getItemPrice(anyInt())).thenReturn(100L);
        when(mockComposition.getMembersName()).thenReturn("Test Item");
        when(mockComposition.getHaPrice()).thenReturn(50);
        when(mockComposition.getNote()).thenReturn(-1);
        when(mockComposition.getLinkedNoteId()).thenReturn(-1);
        when(mockPanel.getSelectedTrackingMode()).thenReturn(0);

        EnhancedLootTrackerConfig mockConfig = mock(EnhancedLootTrackerConfig.class);
        when(mockConfig.maxDrops()).thenReturn(500);
        when(mockConfig.maxTrips()).thenReturn(50);
        when(mockConfig.showLootInChat()).thenReturn(false);

        executor = Executors.newSingleThreadScheduledExecutor();

        setField(plugin, "client", mockClient);
        setField(plugin, "itemManager", mockItemManager);
        setField(plugin, "panel", mockPanel);
        setField(plugin, "config", mockConfig);
        setField(plugin, "storageService", mockStorageService);
        setField(plugin, "chatMessageManager", mock(net.runelite.client.chat.ChatMessageManager.class));
        setField(plugin, "executor", executor);
        setField(plugin, "clientToolbar", mock(ClientToolbar.class));
    }

    @After
    public void tearDown() {
        executor.shutdownNow();
    }

    // === Immediate Save Tests ===

    @Test
    public void testSingleDropTriggersImmediateSave() throws Exception {
        fireNpcDrop("Goblin", 5, 526, 1);

        // saveDrops and saveTrips should be called immediately (no debounce)
        verify(mockStorageService, times(1)).saveDrops(any());
        verify(mockStorageService, times(1)).saveTrips(any());
    }

    @Test
    public void testMultipleDropsEachTriggerSave() throws Exception {
        fireNpcDrop("Goblin", 5, 526, 1);
        fireNpcDrop("Guard", 21, 995, 30);
        fireNpcDrop("Man", 2, 526, 1);

        // Each drop triggers its own save
        verify(mockStorageService, times(3)).saveDrops(any());
        verify(mockStorageService, times(3)).saveTrips(any());
    }

    @Test
    public void testSaveContainsCorrectDropCount() throws Exception {
        fireNpcDrop("Goblin", 5, 526, 1);
        fireNpcDrop("Guard", 21, 995, 30);
        fireNpcDrop("Man", 2, 526, 1);

        // The last save should contain all 3 drops
        verify(mockStorageService).saveDrops(argThat(drops -> drops.size() == 3));
    }

    // === Shutdown Sequence Tests ===

    @Test
    public void testShutdownPerformsSyncSave() throws Exception {
        fireNpcDrop("Guard", 21, 526, 1);

        setField(plugin, "currentAccountHash", 12345L);
        setField(plugin, "dataLoaded", true);
        invokeShutDown();

        verify(mockStorageService).saveTripsSync(any());
        verify(mockStorageService).saveDropsSync(any());
        verify(mockStorageService).saveLastSessionEpoch(anyLong());
    }

    @Test
    public void testShutdownSkipsSyncSaveWhenNoAccount() throws Exception {
        fireNpcDrop("Guard", 21, 526, 1);

        setField(plugin, "currentAccountHash", -1L);
        invokeShutDown();

        verify(mockStorageService, never()).saveTripsSync(any());
        verify(mockStorageService, never()).saveDropsSync(any());
    }

    @Test
    public void testShutdownSkipsSyncSaveWhenDataNotLoaded() throws Exception {
        // Simulates the #26 race: an account is set (startUp ran) but the deferred
        // loadPersistedData() has NOT executed, so in-memory state is empty and must not be
        // written over the real files.
        setField(plugin, "currentAccountHash", 12345L);
        setField(plugin, "dataLoaded", false);

        invokeShutDown();

        verify(mockStorageService, never()).saveTripsSync(any());
        verify(mockStorageService, never()).saveDropsSync(any());
        verify(mockStorageService, never()).saveLastSessionEpoch(anyLong());
    }

    @Test
    public void testSyncSaveOnShutdownContainsAllDrops() throws Exception {
        fireNpcDrop("Goblin", 5, 526, 1);
        fireNpcDrop("Guard", 21, 995, 30);
        fireNpcDrop("Man", 2, 526, 1);

        setField(plugin, "currentAccountHash", 12345L);
        setField(plugin, "dataLoaded", true);
        invokeShutDown();

        verify(mockStorageService).saveDropsSync(argThat(drops -> drops.size() == 3));
    }

    @Test
    public void testShutdownCancelsFarmingDebounceTimer() throws Exception {
        ScheduledFuture<?> farmingTimer = executor.schedule(() -> {}, 10, TimeUnit.SECONDS);
        setField(plugin, "farmingDebounceTimer", farmingTimer);
        setField(plugin, "currentAccountHash", 12345L);

        invokeShutDown();

        assertTrue("farmingDebounceTimer should be cancelled after shutDown", farmingTimer.isCancelled());
    }

    @Test
    public void testShutdownCancelsBirdNestDebounceTimer() throws Exception {
        ScheduledFuture<?> birdNestTimer = executor.schedule(() -> {}, 10, TimeUnit.SECONDS);
        setField(plugin, "birdNestDebounceTimer", birdNestTimer);
        setField(plugin, "currentAccountHash", 12345L);

        invokeShutDown();

        assertTrue("birdNestDebounceTimer should be cancelled after shutDown", birdNestTimer.isCancelled());
    }

    @Test
    public void testShutdownCallsStorageShutdown() throws Exception {
        setField(plugin, "currentAccountHash", 12345L);
        invokeShutDown();

        verify(mockStorageService).shutdown();
    }

    // === Helper methods ===

    private void fireNpcDrop(String npcName, int combatLevel, int itemId, int quantity) {
        NPCComposition mockNpc = mock(NPCComposition.class);
        when(mockNpc.getName()).thenReturn(npcName);
        when(mockNpc.getCombatLevel()).thenReturn(combatLevel);

        plugin.onServerNpcLoot(new ServerNpcLoot(mockNpc,
                Arrays.asList(new ItemStack(itemId, quantity))));
    }

    private void invokeShutDown() throws Exception {
        Method shutDown = EnhancedLootTrackerPlugin.class.getDeclaredMethod("shutDown");
        shutDown.setAccessible(true);
        shutDown.invoke(plugin);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = findField(target.getClass(), fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private Object getField(Object target, String fieldName) throws Exception {
        Field field = findField(target.getClass(), fieldName);
        field.setAccessible(true);
        return field.get(target);
    }

    private Field findField(Class<?> clazz, String fieldName) throws NoSuchFieldException {
        while (clazz != null) {
            try {
                return clazz.getDeclaredField(fieldName);
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            }
        }
        throw new NoSuchFieldException(fieldName);
    }
}

package com.triptracker;

import org.junit.Test;
import static org.junit.Assert.*;

public class DropRecordTest {

    @Test
    public void testRoundTrip() {
        // Create a drop with items
        TrackableItemDrop original = new TrackableItemDrop("Guard", 21, 1000000L);
        original.addLootToDrop(new TrackableDroppedItem(526, "Bones", 1, 30, 10));
        original.addLootToDrop(new TrackableDroppedItem(995, "Coins", 5, 1, 0));

        // Serialize to record
        DropRecord record = DropRecord.fromDrop(original);

        assertEquals("Guard", record.npcName);
        assertEquals(21, record.npcCombatLevel);
        assertEquals(1000000L, record.dropTime);
        assertEquals(2, record.items.size());

        // Deserialize back to drop
        TrackableItemDrop restored = record.toDrop();

        assertEquals("Guard", restored.getDropNpcName());
        assertEquals(21, restored.getDropNpcLevel());
        assertEquals(1000000L, restored.getDropTimeDate());
        assertEquals(2, restored.getDroppedItems().size());
        assertEquals(35, restored.getTotalDropGeValue()); // 30 + 5
    }

    @Test
    public void testItemRecordPreservesPerUnitPrice() {
        TrackableItemDrop drop = new TrackableItemDrop("Man", 2);
        // 10 arrows at 4gp each = 40gp total
        drop.addLootToDrop(new TrackableDroppedItem(882, "Bronze arrow", 10, 4, 1));

        DropRecord record = DropRecord.fromDrop(drop);
        DropRecord.ItemRecord itemRecord = record.items.get(0);

        // Per-unit price should be stored
        assertEquals(4, itemRecord.gePrice);
        assertEquals(1, itemRecord.haPrice);
        assertEquals(10, itemRecord.quantity);

        // Restore and verify total value
        TrackableItemDrop restored = record.toDrop();
        assertEquals(40, restored.getTotalDropGeValue());
    }

    @Test
    public void testLargePriceSurvivesRoundTripWithoutTruncation() {
        // Jagex is widening item/cash-stack values beyond Integer.MAX_VALUE, and
        // RuneLite's getItemPrice now returns a long. A per-unit price above the int
        // ceiling must survive drop -> record -> drop without truncating or going negative.
        long bigPrice = (long) Integer.MAX_VALUE + 1_000_000L; // ~2.148b, overflows int
        TrackableItemDrop original = new TrackableItemDrop("Boss", 500, 1000000L);
        original.addLootToDrop(new TrackableDroppedItem(1234, "Huge stack", 1, bigPrice, 0));

        // Per-unit price is preserved intact in the serialized record
        DropRecord record = DropRecord.fromDrop(original);
        assertEquals(bigPrice, record.items.get(0).gePrice);

        // And after a full restore the total value is intact (no int overflow)
        TrackableItemDrop restored = record.toDrop();
        assertEquals(bigPrice, restored.getTotalDropGeValue());
        assertTrue("value must not go negative from int overflow", restored.getTotalDropGeValue() > 0);
    }

    @Test
    public void testEmptyDrop() {
        TrackableItemDrop drop = new TrackableItemDrop("Chicken", 1);
        DropRecord record = DropRecord.fromDrop(drop);

        assertEquals(0, record.items.size());

        TrackableItemDrop restored = record.toDrop();
        assertEquals(0, restored.getDroppedItems().size());
        assertEquals(0, restored.getTotalDropGeValue());
    }
}

