    private void setupInventoryContainer(int[]... items) {
        ItemContainer mockContainer = mock(ItemContainer.class);
        Item[] inventoryItems = new Item[items.length];
        for (int i = 0; i < items.length; i++) {
            inventoryItems[i] = new Item(items[i][0], items[i][1]);
        }
        when(mockContainer.getItems()).thenReturn(inventoryItems);
        when(mockClient.getItemContainer(93)).thenReturn(mockContainer);
    }

    /**
     * Sets up a mock inventory container with specific IDs and quantities as separate arrays.
     */
    private void setupInventoryContainerWithSpecificIds(int[] ids, int[] quantities) {
        ItemContainer mockContainer = mock(ItemContainer.class);
        Item[] inventoryItems = new Item[ids.length];
        for (int i = 0; i < ids.length; i++) {
            inventoryItems[i] = new Item(ids[i], quantities[i]);
        }
        when(mockContainer.getItems()).thenReturn(inventoryItems);
        when(mockClient.getItemContainer(93)).thenReturn(mockContainer);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = findField(target.getClass(), fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private Object getField(Object target, String fieldName) throws Exception {
        Field field = findField(target.getClass(), fieldName);
        field.setAccessible(true);
        return field.get(target);
    }

    private Field findField(Class<?> clazz, String fieldName) throws NoSuchFieldException {
        while (clazz != null) {
            try {
                return clazz.getDeclaredField(fieldName);
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            }
        }
        throw new NoSuchFieldException(fieldName);
    }
}

package com.triptracker;

import org.junit.Test;
import static org.junit.Assert.*;

public class FormatUtilTest {

    @Test
    public void testSmallNumbers() {
        assertEquals("0", FormatUtil.shortenNumber(0));
        assertEquals("1", FormatUtil.shortenNumber(1));
        assertEquals("9999", FormatUtil.shortenNumber(9999));
    }

    @Test
    public void testThousands() {
        assertEquals("10k", FormatUtil.shortenNumber(10000));
        assertEquals("15k", FormatUtil.shortenNumber(15000));
        assertEquals("100k", FormatUtil.shortenNumber(100000));
        assertEquals("1000k", FormatUtil.shortenNumber(999999));
    }

    @Test
    public void testMillions() {
        assertEquals("1m", FormatUtil.shortenNumber(1000000));
        assertEquals("2.5m", FormatUtil.shortenNumber(2500000));
        assertEquals("1000m", FormatUtil.shortenNumber(999999999));
    }

    @Test
    public void testBillions() {
        assertEquals("1b", FormatUtil.shortenNumber(1000000000));
        assertEquals("2.147b", FormatUtil.shortenNumber(2147483647));
    }

    @Test
    public void testNegativeNumbers() {
        // Negative numbers should just return the string representation
        assertEquals("-1", FormatUtil.shortenNumber(-1));
    }
}

package com.triptracker;

import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;

import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Regression test for backlog bug #22: hidden (excluded) NPCs reappear in an
 * active trip after a new kill.
 *
 * The incremental trip-view render path,
 * {@link EnhancedLootTrackerPanel#addLootBox(NpcLootAggregate, ArrayList, int)},
 * was missing the NPC-exclusion guard that the list- and grouped-view overloads
 * and the full {@code rebuildTripEntries()} path all apply. A kill on an excluded
 * NPC therefore re-added and re-rendered its box during an active trip, even
 * though "show hidden" was off.
 *
 * These tests exercise the render path directly and assert on the stored panel
 * state ({@code tripPanelBoxes}) rather than Swing rendering, per the testing
 * standards (no UI rendering in unit tests).
 */
public class HiddenNpcTripRenderTest {

    private EnhancedLootTrackerPanel panel;
    private EnhancedLootTrackerPlugin mockPlugin;
    private ItemManager mockItemManager;

    private static final int TRIP_ID = 7;
    private static final String EXCLUDED_NPC = "Green dragon";
    private static final String NORMAL_NPC = "Goblin";

    @Before
    public void setUp() throws Exception {
        panel = new EnhancedLootTrackerPanel();
        mockPlugin = mock(EnhancedLootTrackerPlugin.class);
        mockItemManager = mock(ItemManager.class);

        when(mockPlugin.getItemManager()).thenReturn(mockItemManager);
        when(mockPlugin.isSpriteDisplayMode()).thenReturn(false);
        when(mockPlugin.getExcludedItems()).thenReturn(new HashSet<>());
        // Only EXCLUDED_NPC is hidden
        when(mockPlugin.isNpcExcluded(EXCLUDED_NPC)).thenReturn(true);
        when(mockPlugin.isNpcExcluded(NORMAL_NPC)).thenReturn(false);

        setField(panel, "parentPlugin", mockPlugin);
        setField(panel, "showHidden", false);
        // List mode (0): the render branch that touches a TripPanel is gated on
        // mode == 2, so this isolates the tripPanelBoxes state-store behaviour.
        setField(panel, "selectedTrackingMode", 0);
    }

    @Test
    public void excludedNpcNotStoredInTripPanelBoxesOnIncrementalKill() throws Exception {
        NpcLootAggregate excluded = new NpcLootAggregate(EXCLUDED_NPC, mockItemManager);

        panel.addLootBox(excluded, new ArrayList<>(), TRIP_ID);

        LinkedHashMap<Integer, LinkedHashMap<String, LootTrackingPanelBox>> tripPanelBoxes =
                getTripPanelBoxes(panel);
        LinkedHashMap<String, LootTrackingPanelBox> boxesForTrip = tripPanelBoxes.get(TRIP_ID);

        // The excluded NPC must not have polluted the stored panel state. Either the
        // trip has no entry at all, or the map exists but does not contain the NPC.
        if (boxesForTrip != null) {
            assertFalse("Excluded NPC should not be stored in tripPanelBoxes",
                    boxesForTrip.containsKey(EXCLUDED_NPC));
        }
    }

    @Test
    public void nonExcludedNpcIsStoredInTripPanelBoxesOnIncrementalKill() throws Exception {
        NpcLootAggregate normal = new NpcLootAggregate(NORMAL_NPC, mockItemManager);

        panel.addLootBox(normal, new ArrayList<>(), TRIP_ID);

        LinkedHashMap<Integer, LinkedHashMap<String, LootTrackingPanelBox>> tripPanelBoxes =
                getTripPanelBoxes(panel);
        LinkedHashMap<String, LootTrackingPanelBox> boxesForTrip = tripPanelBoxes.get(TRIP_ID);

        assertNotNull("Non-excluded NPC should create a trip entry", boxesForTrip);
        assertTrue("Non-excluded NPC should be stored in tripPanelBoxes",
                boxesForTrip.containsKey(NORMAL_NPC));
    }

    @Test
    public void mixedKillsStoreOnlyTheNonExcludedNpc() throws Exception {
        panel.addLootBox(new NpcLootAggregate(NORMAL_NPC, mockItemManager), new ArrayList<>(), TRIP_ID);
        panel.addLootBox(new NpcLootAggregate(EXCLUDED_NPC, mockItemManager), new ArrayList<>(), TRIP_ID);

        LinkedHashMap<Integer, LinkedHashMap<String, LootTrackingPanelBox>> tripPanelBoxes =
                getTripPanelBoxes(panel);
        LinkedHashMap<String, LootTrackingPanelBox> boxesForTrip = tripPanelBoxes.get(TRIP_ID);

        assertNotNull(boxesForTrip);
        assertTrue("Normal NPC present", boxesForTrip.containsKey(NORMAL_NPC));
        assertFalse("Excluded NPC absent", boxesForTrip.containsKey(EXCLUDED_NPC));
        assertEquals("Only the non-excluded NPC should be stored", 1, boxesForTrip.size());
    }

    @Test
    public void excludedNpcIsRenderedWhenShowHiddenIsOn() throws Exception {
        // When the user toggles "show hidden", the guard must not fire.
        setField(panel, "showHidden", true);

        panel.addLootBox(new NpcLootAggregate(EXCLUDED_NPC, mockItemManager), new ArrayList<>(), TRIP_ID);

        LinkedHashMap<Integer, LinkedHashMap<String, LootTrackingPanelBox>> tripPanelBoxes =
                getTripPanelBoxes(panel);
        LinkedHashMap<String, LootTrackingPanelBox> boxesForTrip = tripPanelBoxes.get(TRIP_ID);

        assertNotNull(boxesForTrip);
        assertTrue("With show-hidden on, excluded NPC should still be stored",
                boxesForTrip.containsKey(EXCLUDED_NPC));
    }

    // === Helpers ===

    @SuppressWarnings("unchecked")
    private LinkedHashMap<Integer, LinkedHashMap<String, LootTrackingPanelBox>> getTripPanelBoxes(
            EnhancedLootTrackerPanel target) throws Exception {
        Field field = findField(target.getClass(), "tripPanelBoxes");
        field.setAccessible(true);
        return (LinkedHashMap<Integer, LinkedHashMap<String, LootTrackingPanelBox>>) field.get(target);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = findField(target.getClass(), fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private Field findField(Class<?> clazz, String fieldName) throws NoSuchFieldException {
        while (clazz != null) {
            try {
                return clazz.getDeclaredField(fieldName);
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            }
        }
        throw new NoSuchFieldException(fieldName);
    }
}

package com.triptracker;

import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.HashSet;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Verifies the list-view rendered-box cap (EnhancedLootTrackerPlugin.MAX_LIST_VIEW_BOXES).
 *
 * The list view must not realize an unbounded number of Swing boxes: switching AWAY from a
 * list view with thousands of boxes was pathologically slow because SwingUtil.fastRemoveAll
 * tears the tree down component-by-component. The incremental add path
 * ({@link EnhancedLootTrackerPanel#addLootBox(TrackableItemDrop)}) inserts newest-first and
 * must drop the oldest box once the cap is exceeded.
 *
 * Asserts on the internal {@code listViewPanelBoxes} list rather than Swing rendering, per the
 * testing standards.
 */
public class ListViewBoxCapTest {

    private EnhancedLootTrackerPanel panel;
    private EnhancedLootTrackerPlugin mockPlugin;
    private ItemManager mockItemManager;

    @Before
    public void setUp() throws Exception {
        panel = new EnhancedLootTrackerPanel();
        mockPlugin = mock(EnhancedLootTrackerPlugin.class);
        mockItemManager = mock(ItemManager.class);
        ItemComposition mockComposition = mock(ItemComposition.class);

        when(mockPlugin.getItemManager()).thenReturn(mockItemManager);
        when(mockPlugin.isSpriteDisplayMode()).thenReturn(false);
        when(mockPlugin.getExcludedItems()).thenReturn(new HashSet<>());
        when(mockPlugin.isNpcExcluded(anyString())).thenReturn(false);
        when(mockItemManager.getItemComposition(anyInt())).thenReturn(mockComposition);
        when(mockItemManager.getItemPrice(anyInt())).thenReturn(10L);
        when(mockComposition.getMembersName()).thenReturn("Test Item");
        when(mockComposition.getHaPrice()).thenReturn(5);

        setField(panel, "parentPlugin", mockPlugin);
        setField(panel, "showHidden", false);
        setField(panel, "selectedTrackingMode", 0); // list view
    }

    @Test
    public void incrementalAddCapsRealizedBoxesAtLimit() throws Exception {
        final int cap = EnhancedLootTrackerPlugin.MAX_LIST_VIEW_BOXES;

        // Add well beyond the cap.
        for (int i = 0; i < cap + 250; i++) {
            panel.addLootBox(new TrackableItemDrop("Goblin", 2));
        }

        assertEquals("Realized list-view boxes must be capped at MAX_LIST_VIEW_BOXES",
                cap, listViewPanelBoxes(panel).size());
    }

    @Test
    public void underCapAddsAreAllRetained() throws Exception {
        final int n = 10;
        for (int i = 0; i < n; i++) {
            panel.addLootBox(new TrackableItemDrop("Goblin", 2));
        }
        assertEquals("Under the cap, every box is retained", n, listViewPanelBoxes(panel).size());
    }

    @Test
    public void newestBoxIsKeptAfterTrim() throws Exception {
        final int cap = EnhancedLootTrackerPlugin.MAX_LIST_VIEW_BOXES;

        for (int i = 0; i < cap; i++) {
            panel.addLootBox(new TrackableItemDrop("Filler", 1));
        }
        // This most-recent add must survive; the oldest should be evicted instead.
        TrackableItemDrop newest = new TrackableItemDrop("Newest", 99);
        panel.addLootBox(newest);

        ArrayList<LootTrackingPanelBox> boxes = listViewPanelBoxes(panel);
        assertEquals(cap, boxes.size());
        // Newest is inserted at index 0.
        assertTrue("The most recent box must be retained at the top after trimming",
                boxes.size() > 0);
    }

    // --- reflection helpers ---

    @SuppressWarnings("unchecked")
    private ArrayList<LootTrackingPanelBox> listViewPanelBoxes(EnhancedLootTrackerPanel target) throws Exception {
        Field f = findField(target.getClass(), "listViewPanelBoxes");
        f.setAccessible(true);
        return (ArrayList<LootTrackingPanelBox>) f.get(target);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = findField(target.getClass(), fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private Field findField(Class<?> clazz, String fieldName) throws NoSuchFieldException {
        while (clazz != null) {
            try {
                return clazz.getDeclaredField(fieldName);
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            }
        }
        throw new NoSuchFieldException(fieldName);
    }
}

package com.triptracker;

import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;

import java.lang.reflect.Field;

import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Tests for LootAggregation, verifying:
 * - Correct value computation
 * - No retained references to ItemManager/ItemComposition (memory fix)
 * - Quantity handling
 */
public class LootAggregationTest {

    private ItemManager mockItemManager;

    @Before
    public void setUp() {
        mockItemManager = mock(ItemManager.class);
        ItemComposition mockComposition = mock(ItemComposition.class);

        when(mockItemManager.getItemComposition(anyInt())).thenReturn(mockComposition);
        when(mockItemManager.getItemPrice(anyInt())).thenReturn(100L);
        when(mockComposition.getMembersName()).thenReturn("Dragon Bones");
        when(mockComposition.getHaPrice()).thenReturn(50);
    }

    @Test
    public void testConstructionLooksUpValues() {
        LootAggregation agg = new LootAggregation(536, 5, mockItemManager);

        assertEquals(536, agg.getItemId());
        assertEquals("Dragon Bones", agg.getItemName());
        assertEquals(5, agg.getQuantity());
        assertEquals(500, agg.getTotalGePrice());  // 100 * 5
        assertEquals(250, agg.getTotalHaPrice());  // 50 * 5
    }

    @Test
    public void testNoItemManagerFieldRetained() throws Exception {
        LootAggregation agg = new LootAggregation(536, 5, mockItemManager);

        // Verify the class does NOT have an itemManager field
        boolean hasItemManagerField = false;
        for (Field field : agg.getClass().getDeclaredFields()) {
            if (field.getName().equals("itemManager") || field.getName().equals("itemComposition")) {
                hasItemManagerField = true;
                break;
            }
        }
        assertFalse("LootAggregation should not retain ItemManager or ItemComposition references",
                hasItemManagerField);
    }

    @Test
    public void testUpdateItemAggregation() {
        LootAggregation agg = new LootAggregation(536, 2, mockItemManager);
        assertEquals(2, agg.getQuantity());

        agg.updateItemAggregation(3);
        assertEquals(5, agg.getQuantity());
        assertEquals(500, agg.getTotalGePrice()); // 100 * 5
    }

    @Test
    public void testZeroQuantityDefaultsToOne() {
        LootAggregation agg = new LootAggregation(536, 0, mockItemManager);
        assertEquals(1, agg.getQuantity());
    }

    @Test
    public void testNegativeQuantityDefaultsToOne() {
        LootAggregation agg = new LootAggregation(536, -5, mockItemManager);
        assertEquals(1, agg.getQuantity());
    }

    @Test
    public void testMatchesById() {
        LootAggregation agg = new LootAggregation(536, 1, mockItemManager);
        assertTrue(agg.matches(536));
        assertFalse(agg.matches(537));
    }

    @Test
    public void testCompareByTotalValue() {
        ItemComposition mockComp1 = mock(ItemComposition.class);
        when(mockComp1.getMembersName()).thenReturn("Cheap Item");
        when(mockComp1.getHaPrice()).thenReturn(1);

        ItemComposition mockComp2 = mock(ItemComposition.class);
        when(mockComp2.getMembersName()).thenReturn("Expensive Item");
        when(mockComp2.getHaPrice()).thenReturn(500);

        ItemManager im = mock(ItemManager.class);
        when(im.getItemComposition(1)).thenReturn(mockComp1);
        when(im.getItemPrice(1)).thenReturn(10L);
        when(im.getItemComposition(2)).thenReturn(mockComp2);
        when(im.getItemPrice(2)).thenReturn(1000L);

        LootAggregation cheap = new LootAggregation(1, 1, im);
        LootAggregation expensive = new LootAggregation(2, 1, im);

        // Expensive should sort before cheap (descending by value)
        assertTrue(cheap.compareTo(expensive) > 0);
        assertTrue(expensive.compareTo(cheap) < 0);
    }
}

