        when(mockComposition.getHaPrice()).thenReturn(5);
    }

    @Test
    public void testNewAggregateHasZeroKills() {
        NpcLootAggregate aggregate = new NpcLootAggregate("Goblin", mockItemManager);
        assertEquals(0, aggregate.getNumberOfKills());
        assertEquals("Goblin", aggregate.getNpcName());
    }

    @Test
    public void testAddDropIncrementsKillCount() {
        NpcLootAggregate aggregate = new NpcLootAggregate("Goblin", mockItemManager);

        TrackableItemDrop drop1 = new TrackableItemDrop("Goblin", 5, 1000L);
        drop1.addLootToDrop(new TrackableDroppedItem(526, "Bones", 1, 30, 10));
        aggregate.addDropToNpcAggregate(drop1);

        assertEquals(1, aggregate.getNumberOfKills());

        TrackableItemDrop drop2 = new TrackableItemDrop("Goblin", 5, 2000L);
        drop2.addLootToDrop(new TrackableDroppedItem(526, "Bones", 1, 30, 10));
        aggregate.addDropToNpcAggregate(drop2);

        assertEquals(2, aggregate.getNumberOfKills());
    }

    @Test
    public void testAggregationCombinesSameItemIds() {
        NpcLootAggregate aggregate = new NpcLootAggregate("Goblin", mockItemManager);

        // First drop: 1 Bones
        TrackableItemDrop drop1 = new TrackableItemDrop("Goblin", 5, 1000L);
        drop1.addLootToDrop(new TrackableDroppedItem(526, "Bones", 1, 30, 10));
        aggregate.addDropToNpcAggregate(drop1);

        // Second drop: 1 Bones + 3 Coins
        TrackableItemDrop drop2 = new TrackableItemDrop("Goblin", 5, 2000L);
        drop2.addLootToDrop(new TrackableDroppedItem(526, "Bones", 1, 30, 10));
        drop2.addLootToDrop(new TrackableDroppedItem(995, "Coins", 3, 1, 0));
        aggregate.addDropToNpcAggregate(drop2);

        ArrayList<LootAggregation> aggregations = aggregate.aggregateNpcDrops();
        assertNotNull(aggregations);
        assertEquals(2, aggregations.size()); // Bones + Coins

        // Find bones aggregation
        LootAggregation bonesAgg = null;
        LootAggregation coinsAgg = null;
        for (LootAggregation agg : aggregations) {
            if (agg.getItemId() == 526) bonesAgg = agg;
            if (agg.getItemId() == 995) coinsAgg = agg;
        }

        assertNotNull(bonesAgg);
        assertNotNull(coinsAgg);
        assertEquals(2, bonesAgg.getQuantity()); // 1 + 1
        assertEquals(3, coinsAgg.getQuantity()); // 3 from second drop
    }

    @Test
    public void testAggregateNpcDropsReturnsCachedList() {
        NpcLootAggregate aggregate = new NpcLootAggregate("Goblin", mockItemManager);

        TrackableItemDrop drop = new TrackableItemDrop("Goblin", 5, 1000L);
        drop.addLootToDrop(new TrackableDroppedItem(526, "Bones", 1, 30, 10));
        aggregate.addDropToNpcAggregate(drop);

        // Calling aggregateNpcDrops multiple times should return the same cached result
        ArrayList<LootAggregation> first = aggregate.aggregateNpcDrops();
        ArrayList<LootAggregation> second = aggregate.aggregateNpcDrops();
        assertSame(first, second);
    }

    @Test
    public void testRebuildAggregationMapAfterDirectItemAdd() {
        NpcLootAggregate aggregate = new NpcLootAggregate("Goblin", mockItemManager);

        // Simulate what TripRecord.toTrip() does: add items directly to droppedItems
        aggregate.getDroppedItems().add(new TrackableDroppedItem(526, "Bones", 1, 30, 10));
        aggregate.getDroppedItems().add(new TrackableDroppedItem(526, "Bones", 1, 30, 10));
        aggregate.getDroppedItems().add(new TrackableDroppedItem(995, "Coins", 5, 1, 0));

        // Rebuild should produce correct aggregations
        aggregate.rebuildAggregationMap();

        ArrayList<LootAggregation> aggregations = aggregate.getNpcItemAggregations();
        assertNotNull(aggregations);
        assertEquals(2, aggregations.size());

        LootAggregation bonesAgg = null;
        for (LootAggregation agg : aggregations) {
            if (agg.getItemId() == 526) bonesAgg = agg;
        }
        assertNotNull(bonesAgg);
        assertEquals(2, bonesAgg.getQuantity());
    }

    @Test
    public void testPerformanceWithManyDrops() {
        NpcLootAggregate aggregate = new NpcLootAggregate("Goblin", mockItemManager);

        // Simulate 1000 kills with same items — should complete quickly with O(n) approach
        long startTime = System.currentTimeMillis();
        for (int i = 0; i < 1000; i++) {
            TrackableItemDrop drop = new TrackableItemDrop("Goblin", 5, 1000L + i);
            drop.addLootToDrop(new TrackableDroppedItem(526, "Bones", 1, 30, 10));
            drop.addLootToDrop(new TrackableDroppedItem(995, "Coins", 3, 1, 0));
            aggregate.addDropToNpcAggregate(drop);
        }
        long elapsed = System.currentTimeMillis() - startTime;

        assertEquals(1000, aggregate.getNumberOfKills());
        ArrayList<LootAggregation> aggregations = aggregate.aggregateNpcDrops();
        assertEquals(2, aggregations.size());

        // With O(n) implementation, 1000 drops should take well under 1 second
        assertTrue("Aggregation took too long: " + elapsed + "ms", elapsed < 2000);
    }

    @Test
    public void testLastKillTimeUpdated() {
        NpcLootAggregate aggregate = new NpcLootAggregate("Goblin", mockItemManager);

        TrackableItemDrop drop = new TrackableItemDrop("Goblin", 5, 1609459200000L); // 2021-01-01
        drop.addLootToDrop(new TrackableDroppedItem(526, "Bones", 1, 30, 10));
        aggregate.addDropToNpcAggregate(drop);

        assertNotNull(aggregate.getLastKillTime());
        assertTrue(aggregate.getLastKillTime().contains("on"));
    }

    @Test
    public void testGetDroppedItemsContainsAllItems() {
        NpcLootAggregate aggregate = new NpcLootAggregate("Goblin", mockItemManager);

        TrackableItemDrop drop1 = new TrackableItemDrop("Goblin", 5, 1000L);
        drop1.addLootToDrop(new TrackableDroppedItem(526, "Bones", 1, 30, 10));
        aggregate.addDropToNpcAggregate(drop1);

        TrackableItemDrop drop2 = new TrackableItemDrop("Goblin", 5, 2000L);
        drop2.addLootToDrop(new TrackableDroppedItem(995, "Coins", 5, 1, 0));
        aggregate.addDropToNpcAggregate(drop2);

        // droppedItems should contain all individual items (not aggregated)
        assertEquals(2, aggregate.getDroppedItems().size());
    }
}

package com.triptracker;

import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPCComposition;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import org.junit.Before;
import org.junit.Test;

import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Tests verifying the high/medium priority fixes:
 * - numberOfTrips derived from trips.size()
 * - Null safety in getNpcAggregate/updateGroupedViewUI
 * - Thread-safe defensive copies from getListViewDropArray/getTrips
 * - Debounced persistence (no immediate disk writes)
 */
public class PluginFixesTest {

    private EnhancedLootTrackerPlugin plugin;
    private EnhancedLootTrackerPanel mockPanel;
    private TripStorageService mockStorageService;

    @Before
    public void setUp() throws Exception {
        plugin = new EnhancedLootTrackerPlugin();
        Client mockClient = mock(Client.class);
        ItemManager mockItemManager = mock(ItemManager.class);
        ItemComposition mockComposition = mock(ItemComposition.class);
        mockPanel = mock(EnhancedLootTrackerPanel.class);
        mockStorageService = mock(TripStorageService.class);

        when(mockItemManager.getItemComposition(anyInt())).thenReturn(mockComposition);
        when(mockItemManager.getItemPrice(anyInt())).thenReturn(10L);
        when(mockComposition.getMembersName()).thenReturn("Test Item");
        when(mockComposition.getHaPrice()).thenReturn(5);
        when(mockPanel.getSelectedTrackingMode()).thenReturn(0);

        EnhancedLootTrackerConfig mockConfig = mock(EnhancedLootTrackerConfig.class);
        when(mockConfig.maxDrops()).thenReturn(500);
        when(mockConfig.maxTrips()).thenReturn(50);

        setField(plugin, "client", mockClient);
        setField(plugin, "itemManager", mockItemManager);
        setField(plugin, "panel", mockPanel);
        setField(plugin, "config", mockConfig);
        setField(plugin, "storageService", mockStorageService);
        setField(plugin, "chatMessageManager", mock(net.runelite.client.chat.ChatMessageManager.class));

        java.util.concurrent.ScheduledExecutorService debounceExecutor =
                java.util.concurrent.Executors.newSingleThreadScheduledExecutor();
        setField(plugin, "executor", debounceExecutor);
    }

    // === Fix #3: numberOfTrips derived from trips.size() ===

    @Test
    public void testGetNumberOfTripsReflectsActualSize() {
        assertEquals(0, plugin.getNumberOfTrips());

        plugin.initTrip("TRIP 1");
        assertEquals(1, plugin.getNumberOfTrips());

        plugin.initTrip("TRIP 2");
        assertEquals(2, plugin.getNumberOfTrips());
    }

    @Test
    public void testGetNumberOfTripsDecreasesOnRemove() {
        plugin.initTrip("TRIP 1");
        plugin.initTrip("TRIP 2");
        assertEquals(2, plugin.getNumberOfTrips());

        plugin.removeTrip("TRIP 1");
        assertEquals(1, plugin.getNumberOfTrips());
    }

    @Test
    public void testGetNextTripNumberIncrementsCorrectly() {
        int first = plugin.getNextTripNumber();
        plugin.initTrip("TRIP " + first);

        int second = plugin.getNextTripNumber();
        assertTrue("Second trip number (" + second + ") should be > first (" + first + ")",
                second > first);
    }

    // === Fix #4: Null safety in getNpcAggregate ===

    @Test
    public void testGetNpcAggregateReturnsNullForUnknownNpc() {
        assertNull(plugin.getNpcAggregate("NonExistentNpc"));
    }

    @Test
    public void testGetNpcAggregateReturnsNullForNullName() {
        // Should not throw
        assertNull(plugin.getNpcAggregate(""));
    }

    // === Thread safety: defensive copies ===

    @Test
    public void testGetListViewDropArrayReturnsDefensiveCopy() throws Exception {
        NPCComposition mockNpc = mock(NPCComposition.class);
        when(mockNpc.getName()).thenReturn("Goblin");
        when(mockNpc.getCombatLevel()).thenReturn(5);

        plugin.onServerNpcLoot(new ServerNpcLoot(mockNpc,
                Arrays.asList(new ItemStack(526, 1))));

        List<TrackableItemDrop> copy1 = plugin.getListViewDropArray();
        List<TrackableItemDrop> copy2 = plugin.getListViewDropArray();

        // Should be different list instances (defensive copy)
        assertNotSame(copy1, copy2);
        // But same content
        assertEquals(copy1.size(), copy2.size());
    }

    @Test
    public void testGetTripsReturnsDefensiveCopy() {
        plugin.initTrip("TRIP 1");

        List<Trip> copy1 = plugin.getTrips();
        List<Trip> copy2 = plugin.getTrips();

        // Should be different list instances
        assertNotSame(copy1, copy2);
        assertEquals(copy1.size(), copy2.size());
    }

    @Test
    public void testModifyingReturnedListDoesNotAffectPlugin() {
        plugin.initTrip("TRIP 1");

        List<Trip> copy = plugin.getTrips();
        copy.clear(); // Modify the returned copy

        // Original should be unaffected
        assertEquals(1, plugin.getTrips().size());
    }

    // === Active trip management ===

    @Test
    public void testInitTripDeactivatesPreviousTrip() {
        plugin.initTrip("TRIP 1");
        Trip trip1 = plugin.getActiveTrip();
        assertNotNull(trip1);
        assertTrue(trip1.getTripStatus());

        plugin.initTrip("TRIP 2");
        assertFalse(trip1.getTripStatus()); // First trip should be deactivated
        Trip trip2 = plugin.getActiveTrip();
        assertNotNull(trip2);
        assertTrue(trip2.getTripStatus());
        assertEquals("TRIP 2", trip2.getTripName());
    }

    @Test
    public void testGetActiveTripReturnsNullWhenNoTrips() {
        assertNull(plugin.getActiveTrip());
    }

    @Test
    public void testCheckForActiveTripReturnsFalseWhenNoTrips() {
        assertFalse(plugin.checkForActiveTrip());
    }

    @Test
    public void testCheckForActiveTripReturnsTrueWhenActive() {
        plugin.initTrip("TRIP 1");
        assertTrue(plugin.checkForActiveTrip());
    }

    // === Clear all data ===

    @Test
    public void testClearAllDataResetsEverything() throws Exception {
        NPCComposition mockNpc = mock(NPCComposition.class);
        when(mockNpc.getName()).thenReturn("Goblin");
        when(mockNpc.getCombatLevel()).thenReturn(5);

        plugin.onServerNpcLoot(new ServerNpcLoot(mockNpc,
                Arrays.asList(new ItemStack(526, 1))));
        plugin.initTrip("TRIP 1");

        assertTrue(plugin.getListViewDropArray().size() > 0);
        assertTrue(plugin.getTrips().size() > 0);

        plugin.clearAllData();

        assertEquals(0, plugin.getListViewDropArray().size());
        assertEquals(0, plugin.getTrips().size());
        assertEquals(0, plugin.getNumberOfTrips());
        assertNull(plugin.getNpcAggregate("Goblin"));
    }

    // === Helper methods ===

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = findField(target.getClass(), fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private Field findField(Class<?> clazz, String fieldName) throws NoSuchFieldException {
        while (clazz != null) {
            try {
                return clazz.getDeclaredField(fieldName);
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            }
        }
        throw new NoSuchFieldException(fieldName);
    }
}

package com.triptracker;

import com.google.common.collect.HashMultiset;
import com.google.common.collect.Multiset;
import net.runelite.api.*;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import java.lang.reflect.Field;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;

import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.*;

/**
 * Regression tests for backlog bug #23: PvP / Emir's Arena loot mis-attributed to a
 * "Farming Patch".
 *
 * The arena loads a preset combat kit into the inventory (supply box) AND fires a
 * spurious Farming StatChanged on the same tick (reporting the unchanged existing total),
 * plus sets stats to 99 (a farming "level-up"). Together these mis-armed the XP-fallback
 * farming detector, which recorded the whole kit as a "Farming Patch" drop.
 *
 * The fix gates all farming arm-points on {@code isInsidePvpArena()} (staging OR battle),
 * and additionally ignores any Farming StatChanged whose total XP did not increase.
 *
 * The harvest arms during STAGING — before {@code PVP_AREA_CLIENT} flips to 1 — so the
 * gate must cover the staging timer too.
 */
public class PvpArenaFarmingTest {

    private EnhancedLootTrackerPlugin plugin;
    private Client mockClient;
    private ItemManager mockItemManager;
    private ItemComposition mockComposition;
    private EnhancedLootTrackerPanel mockPanel;
    private ScheduledExecutorService debounceExecutor;
    private net.runelite.client.callback.ClientThread mockClientThread;

    @Before
    public void setUp() throws Exception {
        plugin = new EnhancedLootTrackerPlugin();
        mockClient = mock(Client.class);
        mockItemManager = mock(ItemManager.class);
        mockComposition = mock(ItemComposition.class);
        mockPanel = mock(EnhancedLootTrackerPanel.class);
        mockClientThread = mock(net.runelite.client.callback.ClientThread.class);

        when(mockItemManager.getItemComposition(anyInt())).thenReturn(mockComposition);
        when(mockItemManager.getItemPrice(anyInt())).thenReturn(100L);
        when(mockComposition.getMembersName()).thenReturn("Test Item");
        when(mockComposition.getHaPrice()).thenReturn(50);
        when(mockComposition.getNote()).thenReturn(-1);
        when(mockComposition.getLinkedNoteId()).thenReturn(-1);
        when(mockPanel.getSelectedTrackingMode()).thenReturn(0);

        EnhancedLootTrackerConfig mockConfig = mock(EnhancedLootTrackerConfig.class);
        when(mockConfig.maxDrops()).thenReturn(500);
        when(mockConfig.maxTrips()).thenReturn(50);
        when(mockConfig.debugMode()).thenReturn(false);

        doAnswer(invocation -> {
            Runnable r = invocation.getArgument(0);
            r.run();
            return null;
        }).when(mockClientThread).invokeLater(any(Runnable.class));

        debounceExecutor = Executors.newSingleThreadScheduledExecutor();

        setField(plugin, "client", mockClient);
        setField(plugin, "itemManager", mockItemManager);
        setField(plugin, "panel", mockPanel);
        setField(plugin, "config", mockConfig);
        setField(plugin, "storageService", mock(TripStorageService.class));
        setField(plugin, "chatMessageManager", mock(net.runelite.client.chat.ChatMessageManager.class));
        setField(plugin, "executor", debounceExecutor);
        setField(plugin, "clientThread", mockClientThread);
    }

    @After
    public void tearDown() {
        debounceExecutor.shutdownNow();
    }

    // === Arena gate: XP-fallback path (the actual bug path) ===

    @Test
    public void testFarmingXpIgnoredInStagingArea() throws Exception {
        // Staging phase: staging timer active, PVP_AREA_CLIENT not yet set.
        when(mockClient.getVarbitValue(VarbitID.PVPA_STAGINGAREA_TIMEREMAINING)).thenReturn(300);
        when(mockClient.getTickCount()).thenReturn(100);
        setField(plugin, "lastInventoryChangeTick", 100); // supply box loaded kit this tick

        Multiset<Integer> prevSnapshot = HashMultiset.create();
        setField(plugin, "previousReferenceInventorySnapshot", prevSnapshot);

        // Spurious arena Farming XP (a genuine increase, to prove the *location* gate alone stops it)
        StatChanged event = new StatChanged(Skill.FARMING, 50000, 99, 99);
        plugin.onStatChanged(event);

        assertFalse("Farming must not arm in the arena staging area",
                (boolean) getField(plugin, "farmingHarvestInProgress"));
        assertEquals("XP tick must not be recorded in the arena",
                -1, (int) getField(plugin, "lastFarmingXpTick"));
    }

    @Test
    public void testFarmingXpIgnoredInBattleArea() throws Exception {
        // Battle phase: PVP_AREA_CLIENT == 1, timers back to 0.
        when(mockClient.getVarbitValue(VarbitID.PVP_AREA_CLIENT)).thenReturn(1);
        when(mockClient.getTickCount()).thenReturn(200);
        setField(plugin, "lastInventoryChangeTick", 200);

        Multiset<Integer> prevSnapshot = HashMultiset.create();
        setField(plugin, "previousReferenceInventorySnapshot", prevSnapshot);

        StatChanged event = new StatChanged(Skill.FARMING, 50000, 99, 99);
        plugin.onStatChanged(event);

        assertFalse("Farming must not arm in the arena battle area",
                (boolean) getField(plugin, "farmingHarvestInProgress"));
    }

    @Test
    public void testFarmingXpIgnoredWhenBattleTimerActive() throws Exception {
        when(mockClient.getVarbitValue(VarbitID.PVPA_BATTLEAREA_TIMEREMAINING)).thenReturn(300);
        when(mockClient.getTickCount()).thenReturn(150);
        setField(plugin, "lastInventoryChangeTick", 150);

        Multiset<Integer> prevSnapshot = HashMultiset.create();
        setField(plugin, "previousReferenceInventorySnapshot", prevSnapshot);

        StatChanged event = new StatChanged(Skill.FARMING, 50000, 99, 99);
        plugin.onStatChanged(event);

        assertFalse("Farming must not arm while the battle-area timer is running",
                (boolean) getField(plugin, "farmingHarvestInProgress"));
    }

    // === Arena gate: the ItemContainerChanged same-tick branch ===

    @Test
    public void testInventoryChangeSameTickAsXpDoesNotArmInArena() throws Exception {
        // Simulate the reverse ordering: an XP tick was somehow recorded, then the supply
        // box fires ItemContainerChanged on the same tick while in the staging area.
        when(mockClient.getVarbitValue(VarbitID.PVPA_STAGINGAREA_TIMEREMAINING)).thenReturn(300);
        setField(plugin, "lastFarmingXpTick", 100);
        when(mockClient.getTickCount()).thenReturn(100);

        Multiset<Integer> prevSnapshot = HashMultiset.create();
        prevSnapshot.add(952, 1);
        setField(plugin, "referenceInventorySnapshot", prevSnapshot);
        setField(plugin, "previousReferenceInventorySnapshot", prevSnapshot);

        // Supply box dumps a big combat kit into inventory
        setupInventoryContainer(new int[]{952, 1}, new int[]{4587, 1}, new int[]{2434, 3});

        ItemContainer container = mockClient.getItemContainer(93);
        plugin.onItemContainerChanged(new ItemContainerChanged(93, container));

        assertFalse("Same-tick container branch must not arm a harvest in the arena",
                (boolean) getField(plugin, "farmingHarvestInProgress"));
    }

    // === Arena gate: chat-harvest path ===

    @Test
    public void testFarmingChatTriggerIgnoredInArena() throws Exception {
        when(mockClient.getVarbitValue(VarbitID.PVP_AREA_CLIENT)).thenReturn(1);
        setupInventoryContainer(new int[]{952, 1});

        ChatMessage event = new ChatMessage();
        event.setType(ChatMessageType.GAMEMESSAGE);
        event.setMessage("You begin to harvest the herb patch.");
        plugin.onChatMessage(event);

        assertFalse("Chat-harvest trigger must be ignored in the arena",
                (boolean) getField(plugin, "farmingHarvestInProgress"));
    }

    // === Heuristic hardening: ignore Farming XP that did not actually increase ===

    @Test
    public void testFarmingXpWithNoIncreaseIsIgnored() throws Exception {
        // Not in the arena — this guard is a second layer against phantom XP anywhere.
        setField(plugin, "lastKnownFarmingXp", 13034431);
        when(mockClient.getTickCount()).thenReturn(100);
        setField(plugin, "lastInventoryChangeTick", 100);

        Multiset<Integer> prevSnapshot = HashMultiset.create();
        setField(plugin, "previousReferenceInventorySnapshot", prevSnapshot);

        // Same total as before — no real XP gained (the arena's spurious event)
        StatChanged event = new StatChanged(Skill.FARMING, 13034431, 99, 99);
        plugin.onStatChanged(event);

        assertFalse("A Farming StatChanged with no XP increase must not arm a harvest",
                (boolean) getField(plugin, "farmingHarvestInProgress"));
        assertEquals("XP tick must not be recorded for a non-increasing event",
                -1, (int) getField(plugin, "lastFarmingXpTick"));
    }

    @Test
    public void testFarmingXpWithIncreaseStillWorks() throws Exception {
        // A genuine increase outside the arena still arms the fallback path.
        setField(plugin, "lastKnownFarmingXp", 49000);
        when(mockClient.getTickCount()).thenReturn(100);
        setField(plugin, "lastInventoryChangeTick", 100);

        Multiset<Integer> prevSnapshot = HashMultiset.create();
        prevSnapshot.add(952, 1);
        setField(plugin, "previousReferenceInventorySnapshot", prevSnapshot);

        StatChanged event = new StatChanged(Skill.FARMING, 50000, 50, 50);
        plugin.onStatChanged(event);

        assertTrue("A genuine Farming XP increase should still arm the harvest outside the arena",
                (boolean) getField(plugin, "farmingHarvestInProgress"));
    }

    // === Control: normal farming outside the arena is unaffected ===

    @Test
    public void testFarmingChatTriggerWorksOutsideArena() throws Exception {
        // All arena varbits default to 0 (not stubbed) → not in arena.
        setupInventoryContainer(new int[]{952, 1});

        ChatMessage event = new ChatMessage();
        event.setType(ChatMessageType.GAMEMESSAGE);
        event.setMessage("You begin to harvest the herb patch.");
        plugin.onChatMessage(event);

        assertTrue("Normal farming must still work outside the arena",
                (boolean) getField(plugin, "farmingHarvestInProgress"));
        assertEquals("herb patch", getField(plugin, "farmingPatchType"));
    }

    // === Helpers ===

    private void setupInventoryContainer(int[]... items) {
        ItemContainer mockContainer = mock(ItemContainer.class);
        Item[] inventoryItems = new Item[items.length];
        for (int i = 0; i < items.length; i++) {
            inventoryItems[i] = new Item(items[i][0], items[i][1]);
        }
        when(mockContainer.getItems()).thenReturn(inventoryItems);
        when(mockClient.getItemContainer(93)).thenReturn(mockContainer);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = findField(target.getClass(), fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private Object getField(Object target, String fieldName) throws Exception {
        Field field = findField(target.getClass(), fieldName);
        field.setAccessible(true);
        return field.get(target);
    }

    private Field findField(Class<?> clazz, String fieldName) throws NoSuchFieldException {
        while (clazz != null) {
            try {
                return clazz.getDeclaredField(fieldName);
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            }
        }
        throw new NoSuchFieldException(fieldName);
    }
}

